const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={today:'我的今天',panorama:'人生全景',goals:'目标与计划',advisors:'顾问书房',reading:'顾问书房',notes:'想法与复盘',review:'个人阶段复盘',chat:'与 Codex 协作',knowledge:'我的知识库',process:'连接与留底'};
