const clip=(s,n=100)=>String(plain(s)).length>n?String(plain(s)).slice(0,n)+'…':String(plain(s));
const domains=()=>list(S?.plan?.domains),domain=id=>domains().find(x=>x.id===id),advisor=n=>S.advisors.find(a=>a.name===n||a.slug===n),nameOf=a=>a?.name||a?.slug||'';
const safeURL=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
