function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4800)}
async function api(path,d,renewed=false){let r;try{r=await fetch(path,{method:d!==undefined?'POST':'GET',headers:d!==undefined?{'Content-Type':'application/json','X-Desk-Token':S?.token||''}:{},body:d!==undefined?JSON.stringify(d):undefined})}catch{throw Error('本地服务连接中断，输入已保留。恢复服务后请重试。')}let x;try{x=await r.json()}catch{throw Error('服务没有返回可读结果，请保留输入后重试。')}if(!r.ok){if(r.status===403&&d!==undefined&&!renewed&&x.error==='会话已更新，请刷新页面'){const fresh=await api('/api/state');S.token=fresh.token;return api(path,d,true)}throw Error(x.error||'操作没有完成，请重试')}if(d!==undefined&&path!=='/api/chat/preview')phaseCache.clear();return x}
async function refresh(render=true){if(!dataScope){const identity=await api('/api/identity');dataScope=identity.data_id;loadDraftStore()}S=await api('/api/state');for(const k of ['goals','notes','learning','sessions','jobs','advisors','captures'])S[k]||=[];$('#topstatus').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});if(render)await draw()}
function phaseKey(days=phaseDays){return dataScope+':'+days}
function currentPhase(){return phaseCache.get(phaseKey())?.data||null}
function phaseError(){return phaseErrors.get(phaseKey())||''}
async function loadPhase(force=false){const key=phaseKey(),days=phaseDays,cached=phaseCache.get(key);if(!force&&cached&&Date.now()-cached.at<60000)return cached.data;if(phasePending.has(key))return phasePending.get(key);const pending=(async()=>{try{const data=await api('/api/phase?days='+days);phaseCache.set(key,{data,at:Date.now()});phaseErrors.delete(key);return data}catch(error){phaseErrors.set(key,'阶段资料暂未读完：'+error.message);return cached?.data||null}finally{phasePending.delete(key)}})();phasePending.set(key,pending);return pending}
async function loadLocalCapabilities(){try{localCapabilities=await api('/api/local/capabilities');localCapabilityError=''}catch(error){localCapabilityError=error.message}}
function modelLabel(id){return list(modelCatalog?.models).find(m=>m.id===id)?.label||id||'工作台目录默认（未确认）'}
function modelSelectorHTML(){const selected=currentDraft().model||'',models=list(modelCatalog?.models).filter(m=>m&&typeof m.id==='string'&&m.id),known=models.some(m=>m.id===selected),groups=['Codex','Gemini'];return `<div class="model-picker"><label for="chat-model">本轮模型</label><select id="chat-model" aria-label="选择本轮模型" title="切换只影响下一轮回复"><option value="" ${!selected?'selected':''} ${modelCatalogError||modelCatalog&&!modelCatalog.default_model?'disabled':''}>跟随本机默认${modelCatalog?.default_model?' · '+esc(modelLabel(modelCatalog.default_model)):modelCatalog?' · 待选择':''}</option>${selected&&!known?`<option value="${esc(selected)}" selected disabled>${esc(selected)} · 待核实</option>`:''}${groups.map(group=>{const rows=models.filter(m=>(m.id.startsWith('gemini-web/')?'Gemini':'Codex')===group);return rows.length?`<optgroup label="${group}">${rows.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''} ${m.selectable===false||modelCatalogError?'disabled':''}>${esc(m.label||m.id)} · ${esc(m.verification||'尚未试答')}</option>`).join('')}</optgroup>`:''}).join('')}</select>${btn('刷新','models-refresh','linkbtn')}${btn(modelCheckState.status==='running'?'停止检查':'检查连接',modelCheckState.status==='running'?'models-stop':'models-check','linkbtn')}</div><small class="model-hint">${modelCatalogError?'模型目录暂未读到；当前选择已保留，可重试刷新。':!modelCatalog?'正在读取当前账户模型目录…':models.length?models.filter(m=>m.selectable===true).length+' 个当前可选模型 · 目录与试答状态分别标注':'当前没有可选模型；保留选择后刷新目录或检查连接。'}</small>`}
function modelConnectionHTML(){const models=list(modelCatalog?.models);return `<section class="panel model-connection"><div class="row spread"><h2>Codex 与 Gemini</h2>${btn('刷新模型','models-refresh','linkbtn')}${btn(modelCheckState.status==='running'?'停止检查':'检查可用模型',modelCheckState.status==='running'?'models-stop':'models-check','linkbtn')}</div><p>工作台目录默认：<strong>${esc(modelLabel(modelCatalog?.default_model))}</strong></p><p class="subtle">${modelCatalogError?'模型目录读取失败；不影响已保存的对话。':models.length?'当前目录提供的型号可直接选择，尚未试答不代表不可选；本机回答核验只表示历史成功；其他Codex客户端或入口的目录可能不同。':'当前目录尚未提供可选模型。'}</p>${models.length?`<details><summary>查看目录提供状态与试答时间</summary><div class="connected-models">${models.map(m=>`<article><strong>${esc(m.label||m.id)}</strong><small>${m.id.startsWith('gemini-web/')?'Gemini':'Codex'} · ${esc(m.id)}</small><small>最近验证：${m.verified_at?esc(time(m.verified_at)):esc(m.verification||'尚未试答')}</small></article>`).join('')}</div></details>`:''}<p class="subtle">在聊天输入框下方选择模型；已经发送的回答继续使用当轮模型。检查只发送固定测试句，不会发送你的草稿或资料。</p>${modelCheckFeedback()}</section>`}
function modelCheckFeedback(){return `<div class="model-check-feedback">${modelCheckState.status==='running'?'<p>正在逐个检查，已完成 '+list(modelCheckState.results).length+' / '+list(modelCheckState.models).length+'；目录提供的模型仍可选择。</p>':''}${list(modelCheckState.results).map(r=>`<p>${esc(modelLabel(r.id))} · ${r.status==='verified'?'已通过验证':'本次未通过'}</p>`).join('')}</div>`}
async function checkModelConnections(){modelCheckState=await api('/api/models/check',{});repaintModels();if(modelCheckWatching)return;modelCheckWatching=true;try{while(modelCheckState.status==='running'){await new Promise(resolve=>setTimeout(resolve,1000));modelCheckState=await api('/api/models/check');await loadModels(true);repaintModels()}toast('模型检查已结束；目录提供状态与试答结果已分别更新。')}catch(e){toast('检查状态暂未读到，可稍后刷新。')}finally{modelCheckWatching=false}}

function repaintModels(){const update=(selector,html)=>{const node=$(selector);if(node&&node.innerHTML!==html)node.innerHTML=html};if(page==='chat'&&document.activeElement?.id!=='chat-model')update('#model-control',modelSelectorHTML());if(page==='process')update('#model-connection',modelConnectionHTML())}
document.addEventListener('focusout',e=>{if(e.target.id==='chat-model')setTimeout(repaintModels,0)});
async function loadModels(force=false,refresh=false){if(modelCatalogPending)return modelCatalogPending;if(!force&&modelCatalog&&Date.now()-modelCatalogAt<60000)return modelCatalog;modelCatalogPending=(async()=>{try{const result=await api('/api/models'+(refresh?'?refresh=1':''));if(!result||!Array.isArray(result.models))throw Error('未取得模型目录');modelCatalog=result;modelCatalogError=result.directory_error||'';modelCatalogAt=Date.now();return result}catch(error){modelCatalogError=error.message;return modelCatalog}finally{modelCatalogPending=null;repaintModels()}})();return modelCatalogPending}
function phaseQuestionKey(){return 'upward-phase-question:'+dataScope+':'+phaseDays}
function open(html,wide=false){$('#modal').classList.toggle('wide',wide);$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){ $('#modal').close() }
function title(h,sub='',action='',eyebrow=''){return `<div class="pagetitle"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(h)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${action}</div>`}
function section(h,action='',eyebrow=''){return `<div class="sectionhead"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h2>${esc(h)}</h2></div>${action}</div>`}
function inlineMD(t){return esc(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`)}
function markdown(text){let code=false,buf=[],out=[],ul=false;const endList=()=>{if(ul){out.push('</ul>');ul=false}};for(const line of String(text||'').split('\n')){if(/^\s*```/.test(line)){endList();if(code){out.push('<pre>'+esc(buf.join('\n'))+'</pre>');buf=[]}code=!code;continue}if(code){buf.push(line);continue}if(/^\s*[-*+]\s+|^\s*\d+[.)]\s+/.test(line)){if(!ul){out.push('<ul>');ul=true}out.push('<li>'+inlineMD(line.replace(/^\s*(?:[-*+]|\d+[.)])\s+/,''))+'</li>');continue}endList();const h=line.match(/^(#{1,6})\s+(.+)$/);if(h){const level=Math.min(h[1].length+1,4);out.push(`<h${level}>${inlineMD(h[2])}</h${level}>`)}else if(/^>\s?/.test(line))out.push('<blockquote>'+inlineMD(line.replace(/^>\s?/,''))+'</blockquote>');else if(/^\s*---+\s*$/.test(line))out.push('<hr>');else if(line.trim())out.push('<p>'+inlineMD(line)+'</p>')}endList();if(buf.length)out.push('<pre>'+esc(buf.join('\n'))+'</pre>');return out.join('')}
function addRef(r){if(selectedRefs.some(x=>x.id===r.id))return;if(selectedRefs.length>=4)throw Error('每轮最多带 4 份资料，请先移除一份。');selectedRefs.push({id:r.id,title:r.title});persistChatState({refs:selectedRefs.map(x=>({...x}))})}
async function navigate(p){stashChat();stashReader();try{await refresh(false)}catch(e){toast('暂未同步最新资料，仍显示已读取的记录。'+e.message)}page=p;viewHasEdits=false;await draw();window.scrollTo({top:0,behavior:'instant'})}
function backgroundCanDraw(){return !viewHasEdits&&!$('#modal')?.open&&!document.activeElement?.matches('input,textarea,select,[contenteditable="true"]')}
async function syncBackground(){if(!S||document.visibilityState==='hidden'||backgroundSync)return;if(page==='chat'){await loadMessages();return}const before=page;backgroundSync=(async()=>{try{await refresh(false);if(page===before&&['today','goals'].includes(page)&&backgroundCanDraw())await draw()}catch{ /* Keep the current page and its input when connectivity changes. */ }finally{backgroundSync=null}})();await backgroundSync}
function announceChange(){try{localStorage.setItem('growth-state-change',String(Date.now()))}catch{}}
function actionError(message){const host=$('#modal')?.open?$('#modalbody'):$('#view');let box=host?.querySelector('.action-error');if(!box&&host){box=document.createElement('div');box.className='action-error';box.setAttribute('role','alert');host.prepend(box)}if(box){box.textContent=message;box.scrollIntoView({block:'nearest'})}toast(message)}
function upsertGoal(saved){if(!saved?.id)throw Error('服务未返回已保存的目标，输入仍保留，请先核对记录。');S.goals=[saved,...S.goals.filter(g=>g.id!==saved.id)]}
async function finishGoalSave(saved){upsertGoal(saved);saveReceipt={id:saved.id,title:saved.title,status:saved.status,unplanned:list(saved.steps).filter(s=>!s.done&&!s.due&&!['draft','proposed'].includes(s.status)).length};close();viewHasEdits=false;page='goals';await draw();announceChange();toast('已保存：'+saved.title+' · '+(statuses[saved.status]||saved.status));try{await refresh(false)}catch{toast('目标已保存。最新列表暂未同步，页面保留本次保存回执。')}}
function captureItemLink(item){const g=S.goals.find(g=>g.id===(item.goal_id||item.id)),n=S.notes.find(n=>n.id===item.id);const label=item.title||g?.title||n?.title||({'goal':'目标','note':'记录','action':'行动'}[item.kind]||'整理条目'),state=item.kind==='note'?(item.index_state||item.status):item.kind==='action'&&item.done===true?'done':item.status;return (g?btn(esc(label),item.kind==='action'&&list(g.steps).some(step=>step.id===item.id)?'step:'+g.id+':'+item.id:'goal:'+g.id,'linkbtn'):n?btn(esc(label),'note:'+n.id,'linkbtn'):esc(label))+' '+tag(statuses[state]||state||'已保存')+(item.kind==='action'&&item.done===false&&!['draft','proposed'].includes(item.status)?' '+tag('待完成'):'')+(item.kind==='action'&&item.due?' '+tag('安排在 '+item.due):'')}

function captureReceiptHTML(c){if(!c)return '';const items=list(c.saved_items);return `${items.length?'<ul class="capture-items">'+items.map(x=>'<li>'+captureItemLink(x)+'</li>').join('')+'</ul>':'<p class="subtle">没有新增已保存条目，原讨论仍然保留。</p>'}${list(c.warnings).length?'<div class="capture-warnings">'+list(c.warnings).map(x=>'<p>'+esc(plain(x)||x.message||'请核对整理结果')+'</p>').join('')+'</div>':''}${c.error?'<p class="action-error">'+esc(c.error)+'</p>':''}${c.source_text?'<details><summary>回看这次依据的原话</summary><pre class="reading">'+esc(c.source_text)+'</pre></details>':''}`}
function recentCaptures(){const rows=list(S.captures).slice(0,3);return rows.length?`<section class="panel recent-captures"><div class="row spread"><h2>最近帮你记下的事</h2><small>按实际保存回执显示</small></div>${rows.map(c=>`<details><summary>${esc(time(c.created_at))} · ${list(c.saved_items).length} 项整理结果${c.status==='partial'?' · 部分保存':c.status==='failed'?' · 保存失败':''}</summary>${captureReceiptHTML(c)}</details>`).join('')}</section>`:''}
function jobCaptureHTML(job){if(!job?.capture_status)return '';if(['failed','partial'].includes(job.capture_status))return `<section class="capture-feedback action-error" role="alert"><strong>${job.capture_status==='partial'?'部分条目已保存，还有内容需要重试':'讨论已完成，但整理没有保存成功'}</strong>${captureReceiptHTML(job.capture_receipt)}<p>${esc(job.capture_error||job.capture_receipt?.error||(job.capture_retryable===true?'可以只重试保存，不重新请求模型。':'没有可重试的结构化整理结果。'))}</p>${job.capture_retryable===true?btn('重试整理已有回复','organize-job:'+job.id,'small'):'<p>原回复已保留。可用回复旁的「形成目标或行动」继续整理，不必重新发送问题。</p>'}</section>`;if(job.capture_status==='empty')return '<section class="capture-feedback"><p>这轮没有明确可记录的目标或行动，讨论已经保留。</p></section>';if(job.capture_status==='saved')return `<section class="capture-feedback"><strong>这轮已整理到工作台</strong>${captureReceiptHTML(job.capture_receipt)}</section>`;return '<p class="subtle">正在整理本轮明确表达的目标与记录…</p>'}
function councilSelectionHTML(selection){return list(selection).length?'<ul class="council-selection">'+list(selection).map(a=>`<li><strong>${esc(a.title||a.name||'顾问')}</strong>${a.reason?'<p>'+esc(a.reason)+'</p>':''}</li>`).join('')+'</ul>':''}
function councilPreviewHTML(c){if(!c)return '';const count=Math.max(0,Number(c.available_count)||0);return `<section class="council-preview"><strong>自动顾问团 · ${count} 位可调度</strong><p>确认发送后，Codex 会根据问题从全库选择 1–4 位顾问，读取其技能正文后回答。不需要先手选顾问。</p><small>本轮分两次模型调用：先选顾问，再结合技能回答；会产生对应调用用量。</small><details><summary>查看可调度目录</summary><p class="subtle">这里只是目录，尚未代表本轮已读取。实际选择和读入正文会在回复依据中留底。</p><ul class="council-catalog">${list(c.catalog).map(a=>`<li><strong>${esc(a.title||a.name)}</strong><span>${esc(a.category||'顾问')}</span></li>`).join('')}</ul></details></section>`}
function jobCouncilHTML(job){if(!job)return '';const selection=list(job.advisor_selection),warnings=list(job.advisor_warnings),running=['queued','running','cancelling'].includes(job.status),phases={selecting:'正在从顾问全库选择适合本题的顾问',reading:'正在读取已选顾问的技能正文',answering:'正在结合已读技能与本轮资料回答'};if(!job.council_phase&&!selection.length&&!warnings.length)return '';return `<section class="council-status" aria-live="polite">${running&&phases[job.council_phase]?'<strong>'+phases[job.council_phase]+'</strong>':''}${selection.length?'<details open><summary>本轮选中的顾问 · '+selection.length+' 位</summary>'+councilSelectionHTML(selection)+'</details>':''}${warnings.length?'<div class="council-warnings">'+warnings.map(w=>'<p>'+esc(typeof w==='string'?w:w.message||w.reason||plain(w))+'</p>').join('')+'</div>':''}${!running&&selection.length?'<small>实际读入内容以这条回复的依据快照为准。</small>':''}</section>`}
function savedGoalNotice(){if(!saveReceipt)return '';return `<section class="save-receipt" role="status" aria-live="polite"><div><strong>已保存「${esc(saveReceipt.title)}」</strong><p>${esc(statuses[saveReceipt.status]||saveReceipt.status)}${saveReceipt.unplanned?' · '+saveReceipt.unplanned+' 个行动尚未排期，未自动安排到今天。':''}</p></div>${btn('查看这项目标','locate-goal:'+saveReceipt.id,'small')}${btn('收起','dismiss-receipt','linkbtn')}</section>`}
function goalConversationEntry(){const g=activeGoals()[0];return `<section class="daily-conversation"><div><small>和 AI 顾问团聊聊</small><strong>${esc(g?'继续推进：'+g.title:'把今天的想法，说出来')}</strong><small>携带近 7 天阶段与方法、进行中与暂停目标 · 回复后整理目标与记录</small></div><label class="sr-only" for="goal-intent">想聊的目标或近况</label><textarea id="goal-intent" rows="1" placeholder="我想做到… / 今天完成了… / 我卡在…">${esc(localStorage.getItem('growth-goal-intent')||'')}</textarea>${btn('开始聊聊 →','goal-chat','primary')}</section>`}

function activeGoals(){return S.goals.filter(g=>g.status==='active')}
function pendingTasks(){return activeGoals().flatMap(g=>list(g.steps).filter(s=>!s.done&&!['draft','proposed'].includes(s.status)).map(s=>({...s,goal:g}))).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||(a.goal.priority||2)-(b.goal.priority||2))}
function todayTasks(){return pendingTasks().filter(t=>t.due&&t.due<=S.date)}
function proposalTask(d,i=0,selectedAction=null){const a=selectedAction||list(d.actions)[0];if(!a)return '';return `<article class="task"><span class="ordinal">0${i+1}</span><div><div class="row spread"><h3>${esc(a.title)}</h3>${tag('建议 · 待取舍','warm')}</div><p>${esc(clip(plain(list(a.steps)[0])||a.completion_evidence||d.plan_draft?.approach,125))}</p><div class="row spread"><small>${esc(d.title)}</small><div class="actions">${btn('查看依据','domain:'+d.id,'linkbtn')}${btn('采用 / 调整 →','adopt:'+d.id+':'+a.id,'linkbtn')}</div></div></div></article>`}
function proposedPicks(){const preferred=list(S.plan?.current_focus_draft?.suggested_action_ids),all=domains().flatMap(d=>list(d.actions).map(a=>({d,a})));return preferred.length?preferred.map(id=>all.find(x=>x.a.id===id)).filter(Boolean):domains().map(d=>({d,a:list(d.actions)[0]})).filter(x=>x.a)}
function actualTask(t){return `<article class="task"><input aria-label="完成 ${esc(t.text)}" type="checkbox" data-step="${esc(t.goal.id)}:${esc(t.id)}"><div><h3>${esc(t.text)}</h3><p>${esc(t.criterion||t.goal.title)}</p><div class="row spread"><small>${t.due?esc(t.due)+(t.due<S.date?' · 待重新安排':''):'尚未安排日期'} · ${esc(t.goal.title)}</small>${btn('安排与结果','step:'+t.goal.id+':'+t.id,'linkbtn')}</div></div></article>`}
function capture(){return `<div class="capture-box"><textarea id="capture" class="capture" placeholder="一个念头、今天的卡点，或刚刚想明白的事……">${esc(localStorage.getItem('growth-draft')||'')}</textarea><div class="actions"><span class="subtle">先留下原话</span><div class="row">${btn('保存','capture-save')}${btn('保存并入库','capture-index')}${btn('带去讨论 ↗','capture-chat','primary')}</div></div></div>`}
function learningPicks(){const chosen=[];for(const d of domains()){for(const slug of list(d.advisor_slugs)){const a=advisor(slug);if(a?.installed&&!chosen.some(x=>nameOf(x.a)===slug)){chosen.push({a,d});break}}if(chosen.length===3)break}if(chosen.length<3)for(const a of S.advisors.filter(x=>x.installed)){if(chosen.some(x=>nameOf(x.a)===nameOf(a)))continue;chosen.push({a,d:null});if(chosen.length===3)break}return chosen}
function learningCard({a,d}){const l=S.learning.find(x=>x.advisor===nameOf(a));return `<article class="card learning-card"><div class="row spread">${tag(d?.title||a.category)}<small>${l?statuses[l.status]||'曾经读过':'从问题出发'}</small></div><h3>${esc(a.title)}</h3><p>${esc(d?.plan_draft?.title||a.review_note||'读一份方法，看看它能怎样回应你眼前的困惑。')}</p><div class="card-meta">${esc(d?.plan_draft?.why?clip(d.plan_draft.why,76):'先读原文，再留下自己的理解。')}</div><div class="row spread">${btn(l?'继续阅读 →':'开始阅读 →','advisor:'+nameOf(a),'linkbtn')}${d?btn('对应的方向','domain:'+d.id,'linkbtn'):''}</div></article>`}
function hasCommitments(){return S.commitments?.connected===true}
function commitmentView(compact=false){const c=S.commitments;if(!hasCommitments())return '';const items=Array.isArray(c.goal_statuses)?c.goal_statuses:Object.entries(c.goal_statuses||{}).map(([title,v])=>typeof v==='string'?{title,status:v}:{title,...v}),next=list(c.next_actions),updated=c.updated_at||c.cutoff;return `<section class="panel commitment-panel"><div class="row spread"><div><div class="eyebrow">沿用你的目标台账</div><h2>本周建议，等你取舍</h2></div>${btn('回读原台账','read:source:canonical-commitments','linkbtn')}</div><p class="subtle">${c.review_on?'下次回看 '+esc(c.review_on):''} · 建议日期不代表已经承诺</p><div class="commitment-actions">${next.map(x=>`<div class="week-item"><strong>${esc(x.deliverable||plain(x)||x.action||x.task||'近期建议')}</strong><p>${esc(x.commitment||x.status||'建议，尚未承诺')}${x.proposed_due?' · 建议 '+esc(x.proposed_due):''}</p>${x.effort?'<small>'+esc(x.effort)+'</small>':''}</div>`).join('')}</div><details class="commitment-history"><summary>已有方向与最近复盘 · ${items.length} 条历史状态</summary><p class="subtle">${esc(c.period||'')}${updated?' · 更新于 '+esc(new Date(updated).toLocaleDateString('zh-CN',{year:'numeric',month:'numeric',day:'numeric'})):''}</p>${items.map(x=>`<div class="week-item"><strong>${esc(x.title||x.goal||x.name||x.direction||'已有方向')}</strong><p>${esc(typeof x.status==='string'?x.status:plain(x.status))}${x.result?' · '+esc(x.result):''}${x.note?' · '+esc(x.note):''}</p></div>`).join('')}<p class="subtle">原台账保持只读。工作台中的采用与执行状态单独留底，不自动改写历史。</p></details></section>`}
function sourceLinks(ids){return [...new Set(list(ids).filter(Boolean))].map(id=>btn('回读：'+esc(sourceTitle(id)),'read:source:'+String(id).replace(/^source:/,''),'linkbtn')).join('')}
function executionLinks(id){return list(S.plan?.execution_links).filter(x=>(!id||x.domain_id===id)&&safeURL(x.url)).map(x=>link(x.url,x.label||'打开原工作台')).join(' · ')}
function todayView(){
 const q=S.quote,tasks=todayTasks(),pending=pendingTasks(),unplanned=pending.filter(t=>!t.due),future=pending.filter(t=>t.due>S.date),learning=learningPicks().slice(0,1);
 const candidates=!tasks.length&&!unplanned.length?proposedPicks().slice(0,2):[];
 return `<section class="hero"><div class="hero-body"><div class="eyebrow">今日提醒 · ${esc(q?.advisor||'成长书房')}</div><blockquote class="${(q?.text||'').length>36?'long-quote':''}">${esc(q?.text||'把值得的事，往前推进一点。')}</blockquote><div class="quote-person">${esc(q?.type||'工作台寄语')} · ${esc(S.date)}</div><p class="reflection">${esc(q?.reflection||'今天，选一个能在真实生活里验证的小行动。')}</p><div class="actions">${btn('聊聊这句提醒','quote-chat','linkbtn')}${btn('出处与原文','quote-source','linkbtn')}${btn('换个视角','quote-next','linkbtn')}</div></div><span class="scene-caption">在自己的书桌前，慢慢生长</span></section>`+
 goalConversationEntry()+Experience.homeSummary(currentPhase(),phaseError())+section('把注意力放回今天',btn('安排阶段计划 →','page:goals','linkbtn'),'行动 · 当日与待重排')+
 (executionLinks('creation')?'<div class="execution-entry">'+executionLinks('creation')+'</div>':'')+
 `<div class="grid today-focus-grid"><section class="panel topline"><div class="row spread"><h2>${tasks.length?'今天与待重排的行动':'今天还没有已排定的行动'}</h2>${tag(tasks.length?tasks.length+' 项到期或待重排':'按自己的节奏','blue')}</div>${tasks.length?'<div class="task-list">'+tasks.map(actualTask).join(''):'<p class="subtle">从已经决定的事里安排一步，或先处理眼前的卡点。</p>'}${unplanned.length?`<details class="unplanned-actions" open><summary>已采用，尚未排期 · ${unplanned.length} 项</summary><p class="subtle">这些是你确认过的行动，尚未指定今天完成。</p>${unplanned.slice(0,3).map(actualTask).join('')}${unplanned.length>3?btn('查看全部未排期行动','page:goals','linkbtn'):''}</details>`:''}${candidates.length?`<div class="unplanned-actions"><h3>还没决定时，可以从这里取舍</h3><small>资料中的候选步骤 · 尚未采用，也没有安排到今天</small><div class="task-list">${candidates.map((x,i)=>proposalTask(x.d,i,x.a)).join('')}</div></div>`:''}${future.length?`<p class="subtle">另有 ${future.length} 项安排在未来，保留在${btn('目标与计划','page:goals','linkbtn')}。</p>`:''}</section><section class="panel today-reading"><div class="eyebrow">今天读一点</div><h2>带着一个问题学习</h2>${learning.length?learning.map(learningCard).join(''):'<p class="subtle">先到顾问书房，选一个与你眼前问题有关的方法。</p>'}${btn('顾问书房 →','page:advisors','linkbtn')}</section></div>`+
 `<div class="daily-close"><span>做过的事，值得留下一点经验。</span>${btn('晚间回顾 →','review:','linkbtn')}${btn('随手记','quick-note','linkbtn')}</div>`+recentCaptures();
}
function panoramaView(){
 const p=S.plan?.life_panorama;if(!p)return title('人生全景','把长期愿望、现实处境与当前阶段放在一起。')+`<section class="panel"><h2>长期全景资料尚未接入</h2><p>现有行动方案不等于你的人生全景。这里需要有来源的个人愿望与阶段记录，接入后才能呈现。</p>${btn('查看已有阶段计划','page:goals','linkbtn')}${btn('讨论我的长期方向','page:chat','primary')}</section>`;
 const n=p.north_star||{},m=p.mastery||{};
 return title(p.title||'人生全景',p.subtitle||'先看想要的生活，再看正在走的路。',btn('查看阶段目标 →','page:goals','linkbtn'),'愿景 · 路径 · 生活')+
 `<section class="vision-hero"><div class="eyebrow">我想要的生活</div><blockquote>${esc(n.quote||'尚未记录本人愿景原话')}</blockquote><div class="vision-caption">${esc(n.status||'材料中的愿望')}${n.date?' · '+esc(n.date):' · 原件日期见出处'}</div>${n.interpretation?'<p>'+esc(n.interpretation)+'</p>':''}<div class="vision-sources">${sourceLinks(n.source_id)}</div>${list(p.route)[0]?`<div class="vision-now"><strong>${esc(p.route[0].title)}</strong><span>${esc(p.route[0].horizon)}</span><small>${esc(p.route[0].status)}</small></div>`:''}</section>`+
 section('这些方向，共同组成我的生活','','愿景地图')+`<div class="vision-grid">${list(p.pillars).map((x,i)=>`<article class="vision-pillar"><div class="vision-number">${String(i+1).padStart(2,'0')}</div><div><h2>${esc(x.title)}</h2><p class="desired-life">${esc(x.desired_life)}</p><p>${esc(x.meaning)}</p><small>${esc(x.status||'从本人材料整理')}</small><details><summary>依据与对应方向</summary><div class="vision-sources">${sourceLinks(x.source_ids)}</div><div class="actions">${list(x.domain_ids).filter(id=>domain(id)).map(id=>btn('相关方案：'+esc(domain(id).title.split(/[：:]/)[0]),'domain:'+id,'linkbtn')).join('')}</div></details></div></article>`).join('')}</div>`+
 section('愿景很远，路径可以调整','','阶段路线')+`<div class="life-route">${list(p.route).map((x,i)=>`<article class="route-stage"><div class="route-anchor">${String(i+1).padStart(2,'0')}</div><div><span class="eyebrow">${esc(x.horizon)}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><small>${esc(x.status)}</small>${x.evidence_needed?'<div class="route-condition"><strong>需要看到什么依据</strong><p>'+esc(plain(x.evidence_needed))+'</p></div>':''}<div class="vision-sources">${sourceLinks(x.source_ids)}</div></div></article>`).join('')}</div>`+
 section(m.title||'让我伟大：让近期工作更专精','','成长方法')+`<section class="panel mastery-panel">${m.quote?'<blockquote>'+esc(m.quote)+'</blockquote>':''}${m.date?'<small class="mastery-date">'+esc(m.date)+'</small>':''}<div class="mastery-steps">${list(m.steps).map((x,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p></div>`).join('')}</div><p class="subtle">${esc(m.boundary||'近期专精指导与长程愿景相互连接，具体行动由本人取舍。')}</p><div class="actions">${btn('按这套方法，讨论当前卡点 →','panorama-discuss:mastery','primary')}${sourceLinks(m.source_id)}</div></section>`+
 section('走得远，也要过好生活','','需要守住的条件')+`<div class="life-boundaries">${list(p.boundaries).map(x=>`<article><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="vision-sources">${sourceLinks(x.source_ids)}</div></article>`).join('')}</div>`+
 (list(p.history).length?`<details class="panel panorama-history"><summary><strong>我的方向怎样走到现在</strong><span class="subtle"> 回看变化与原始依据</span></summary><div class="vision-timeline">${list(p.history).map(x=>`<article><small>${esc(x.date)}</small><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><span class="history-status">${esc(x.status)}</span><div class="vision-sources">${sourceLinks(x.source_ids)}</div></article>`).join('')}</div>${p.history_note?'<p class="subtle">'+esc(p.history_note)+'</p>':''}</details>`:p.history_note?`<aside class="panorama-history"><strong>方向的变化，也值得留下</strong><p>${esc(p.history_note)}</p></aside>`:'');
}
function planCandidate(d){const active=activeGoals().find(g=>g.domain_id===d.id);return `<details class="plan-candidate" id="candidate-${esc(d.id)}"><summary><span><small>${esc(d.title)}</small><strong>${esc(d.plan_draft?.title||d.title)}</strong></span>${tag(active?'已有执行目标':'候选 · 未采用',active?'blue':'warm')}</summary><div class="candidate-body"><p>${esc(d.plan_draft?.why||d.priority_reason)}</p><div class="candidate-criterion"><strong>怎样算做到</strong><p>${esc(d.plan_draft?.success_definition||'查看每一步的完成依据，并按自己的情况调整。')}</p></div><ol>${list(d.actions).map(a=>`<li><strong>${esc(a.title)}</strong><p>${esc(plain(a.completion_evidence))}</p></li>`).join('')}</ol><p class="subtle">回看时机：${esc(d.plan_draft?.review_trigger||'阶段结果或现实条件发生变化时')}</p><div class="actions">${btn(active?'查看执行目标':'采用 / 调整',active?'goal:'+active.id:'adopt:'+d.id,'primary')}${btn('依据与完整方案','domain:'+d.id,'linkbtn')}${executionLinks(d.id)}</div></div></details>`}
function goalsView(){
 const active=activeGoals(),drafts=S.goals.filter(g=>g.status==='draft'||g.status==='proposed'),paused=S.goals.filter(g=>g.status==='paused'),past=S.goals.filter(g=>['done','archived'].includes(g.status)),pending=pendingTasks();
 return title('把方向，变成可检验的阶段结果。','这里管理目标、步骤、排期和结果。人生愿景留在全景，今天只处理当下行动。',btn('和顾问团聊目标 →','goal-chat','primary'),'目标 · 周期 · 结果')+
 savedGoalNotice()+`<div class="plan-overview"><div><strong>${activeGoals().length}</strong><span>正在推进的目标</span></div><div><strong>${pending.filter(t=>t.due).length}</strong><span>已安排日期的行动</span></div><div><strong>${pending.filter(t=>!t.due).length}</strong><span>已采用、尚未排期</span></div></div>`+
 section('我决定推进的阶段结果',btn('回看人生全景 →','page:panorama','linkbtn'))+`<section class="panel">${active.length?active.map(goalCard).join(''):'<div class="plan-empty"><h3>还没有确认采用的阶段目标</h3><p>下方的候选方案已整理好依据、步骤与完成标准。你可以直接取舍和修改，不必从空白页填写。</p></div>'}</section>`+
 (drafts.length?section('草稿与待确认目标')+`<section class="panel"><p class="subtle">这些目标已保存为草稿，尚未开始。确认推进某一项后，它才会进入行动安排。</p>${drafts.map(goalCard).join('')}</section>`:'')+
 (paused.length?`<details class="panel"><summary>暂缓中的目标 · ${paused.length} 项</summary><p class="subtle">保留安排与结果，恢复后再进入当日行动。</p>${paused.map(goalCard).join('')}</details>`:'')+
 section('候选方案，按需要展开','','取舍与安排')+`<section class="panel candidate-list">${domains().map(planCandidate).join('')||'<p class="subtle">尚未接入个人阶段方案，可以先记录自己的目标。</p>'}</section>`+
 (hasCommitments()?`<details class="panel plan-ledger"><summary><strong>原目标台账与本周建议</strong><span class="subtle"> 保留来源，不自动变成新承诺</span></summary>${commitmentView()}</details>`:'')+
 (past.length?`<details class="panel"><summary>已完成与归档目标 · ${past.length} 项</summary>${past.map(goalCard).join('')}</details>`:'');
}
function recordOrigin(id){return /^(message|note|capture):[a-f0-9]+$/.test(id||'')?btn(id.startsWith('message:')?'回看原讨论':id.startsWith('capture:')?'回看整理依据':'回看原记录','read:'+id,'linkbtn'):''}
function goalCard(g){const steps=list(g.steps),adopted=steps.filter(s=>!['draft','proposed'].includes(s.status)),done=adopted.filter(s=>s.done).length;return `<article class="goal ${saveReceipt?.id===g.id?'saved-goal':''}" id="goal-${esc(g.id)}"><div class="row spread"><h3>${esc(g.title)}</h3>${tag(statuses[g.status]||g.status,g.status==='active'?'blue':'')}</div><p class="goal-why">${esc(g.why)}${g.due?' · '+esc(g.due):''}</p><div class="row spread"><small>${esc(domain(g.domain_id)?.title||g.domain||'个人目标')} · ${done} / ${adopted.length} 个行动完成</small>${g.parent_id?tag('连接长期方向'):''}</div><progress class="goal-progress" value="${done}" max="${Math.max(1,adopted.length)}" aria-label="${esc(g.title)}：${done} / ${adopted.length} 个行动完成">${adopted.length?Math.round(done/adopted.length*100):0}%</progress>${steps.map(t=>['draft','proposed'].includes(t.status)?`<div class="candidate-step"><strong>${esc(t.text)}</strong>${tag('候选 · 未采用','warm')}<div class="actions">${btn('采用这一步','activate-step:'+g.id+':'+t.id,'small')}${recordOrigin(t.source_id)}</div></div>`:`<label class="step"><input type="checkbox" aria-label="完成 ${esc(t.text)}" data-step="${esc(g.id)}:${esc(t.id)}" ${t.done?'checked':''}><span>${esc(t.text)}</span></label><div class="step-meta">${t.due?esc(t.due)+' · ':''}${esc(t.outcome||t.criterion||'')}${btn(t.outcome?'查看结果':'安排与结果','step:'+g.id+':'+t.id,'linkbtn')}${recordOrigin(t.source_id)}</div>`).join('')}<div class="actions">${['draft','proposed'].includes(g.status)?btn('确认开始这项目标','activate-goal:'+g.id,'primary'):''}${btn('调整目标（可选）','goal:'+g.id,'small')}${btn('一次复盘','review:'+g.id,'small')}${btn('与顾问讨论','discuss-goal:'+g.id,'linkbtn')}${recordOrigin(g.origin_id)}</div></article>`}
async function draw(){if(!S)return;clearTimeout(poll);const drawingPage=page,drawingPhase=phaseKey();if(['today','notes','review'].includes(page))await loadPhase();if(page==='process')await Promise.all([loadLocalCapabilities(),loadModels()]);if(page!==drawingPage||(['today','notes','review'].includes(page)&&phaseKey()!==drawingPhase))return;$('#crumb').textContent=labels[page]||labels.today;document.querySelectorAll('[data-page]').forEach(n=>n.classList.toggle('active',n.dataset.page===(page==='reading'?'advisors':page)));const v=$('#view');v.classList.toggle('chat-view',page==='chat');
if(page==='today'){v.innerHTML=todayView();
}else if(page==='panorama'){v.innerHTML=panoramaView();
}else if(page==='goals'){v.innerHTML=goalsView();
}else if(page==='advisors'){v.innerHTML=title('顾问书房','先找当前问题，再读方法与原文。理解留给自己，运用落到真实行动。')+continuedReading()+methodSection()+`<section class="panel library-panel"><div class="panel-heading row spread"><h2>按人生问题找顾问</h2><small>${S.stats.installed} 个本机可读 · ${S.stats.advisors} 个来源入口</small></div><div class="library-content"><div class="category-tiles">${domains().map(d=>`<button class="category-tile" data-action="library-domain:${esc(d.id)}"><strong>${esc(d.title)}</strong><small>${esc(clip(d.plan_draft?.title,36))}</small></button>`).join('')}</div><div class="toolbar"><input id="advisor-search" aria-label="搜索顾问与方法" placeholder="顾问名，或你正在面对的问题……" value="${esc(advisorQuery)}"><select id="category" aria-label="领域筛选"><option value="">所有类别</option>${[...new Set(S.advisors.map(a=>a.category))].map(c=>`<option ${c===advisorCategory?'selected':''}>${esc(c)}</option>`).join('')}</select>${btn('全部','library-all','small')}</div><div id="advisor-results">${advisorTable()}</div></div></section>`;
}else if(page==='reading'){await renderReader();
}else if(page==='notes'){v.innerHTML=Experience.notesView(currentPhase(),{days:phaseDays,error:phaseError(),notes:S.notes})+`<details class="notes-capture"><summary>随手记 · 留下一个新念头</summary>${capture()}</details><div class="sectionhead"><h2>${showArchived?'归档记录':'全部保存记录'}</h2>${btn(showArchived?'返回最近':'查看归档','toggle-archive','linkbtn')}</div><details class="all-records" ${showArchived?'open':''}><summary>${showArchived?'查看归档与恢复入口':'展开所有记录与编辑入口'} · ${S.notes.filter(n=>Boolean(n.archived)===showArchived).length} 条</summary>${S.notes.filter(n=>Boolean(n.archived)===showArchived).map(noteCard).join('')||'<p class="phase-empty">还没有这一类记录。</p>'}</details>`;
}else if(page==='review'){renderReview(v);
}else if(page==='chat'){renderChat(v);await loadMessages();
}else if(page==='knowledge'){v.innerHTML=title('把读过和做过，变成下一次的依据。','搜索原资料、学习记录与自己的经验。先回读，再决定如何使用。')+`<div class="toolbar"><input id="knowledge-query" aria-label="搜索知识库" placeholder="例如：实践、AI 学习、职业、预算……" value="${esc(knowledgeQuery)}">${btn('搜索知识库','search','primary')}</div><section class="panel" id="search-results"><div class="row spread"><h2>我的知识与经验</h2>${tag(S.stats.documents+' 份已索引资料')}</div>${S.notes.slice(0,4).map(n=>`<div class="search-result"><h3>${esc(n.title)}</h3><p>${esc(clip(n.body,150))}</p>${btn('回读记录','read:note:'+n.id,'linkbtn')}</div>`).join('')||'<p class="muted">从一个具体词开始。查找到的内容保留来源，原文不会自动发送到模型。</p>'}</section>`;
}else if(page==='process'){v.innerHTML=Experience.capabilities(localCapabilities,localCapabilityError,S.jobs.flatMap(j=>list(j.local_actions)))+title('连接与留底','数据、过程与可复用方法，各有自己的去处。')+`<div class="stats"><div class="stat"><b>${S.stats.advisors}</b><small>顾问来源 / ${S.stats.installed} 个本机可读</small></div><div class="stat"><b>${S.stats.methods}</b><small>本项目登记的方法流程</small></div><div class="stat"><b>${S.stats.documents}</b><small>统一索引文档，不等于独立证据数</small></div></div><div class="equal-grid"><section class="panel"><h2>本机连接</h2><p>Codex：${S.connection.codex_available?'本机程序可用':'尚未配置'}</p><p>最近一轮：${statuses[S.connection.last_codex]||'还没有实际发送'}</p><p>知识库：${S.connection.knowledge_connected?'本地索引已连接':'尚未连接，可继续保存本地记录'}</p><small>工作台保留自己的对话历史，不恢复桌面端原聊天。</small></section><section class="panel"><h2>私人内容与公开方法</h2><p>个人资料、目标、想法和对话保存在私人目录。公开包单独审查，不包含这些内容。</p><p>第三方顾问按各自许可处理，公开目录不等于所有正文都可再分发。宣传创作资料保持私有。</p></section></div>`+`<div id="model-connection">${modelConnectionHTML()}</div>`+section('最近操作留底')+'<section class="panel" id="audit-list"></section>';const r=await api('/api/audit');$('#audit-list').innerHTML=r.events.slice(0,30).map(e=>{let d={};try{d=JSON.parse(e.detail)}catch{}return `<div class="timeline">${esc(e.action)} · ${esc(d.kind||'记录')}<small>${time(e.at)} · ${esc(e.object_id?.slice(0,10))} · 版本 ${esc(d.rev)}</small></div>`}).join('')||'<p class="subtle">还没有操作记录。</p>'}
}

function methodSection(){const ms=list(S.methods);if(!ms.length)return '';return `<details class="panel method-section"><summary><strong>方法架 · ${ms.length} 条去重方法</strong><span class="subtle"> 从读懂到运用，选择一条具体路径</span></summary><div class="method-grid">${ms.map(m=>`<button data-action="method:${esc(m.id)}"><strong>${esc(m.title)}</strong><small>${esc(clip(plain(list(m.steps)[0]),55))}</small></button>`).join('')}</div><p class="subtle">这是项目登记的去重方法，不代表所有顾问原文方法的总数。</p></details>`}

function advisorDomains(a){return domains().filter(d=>list(d.advisor_slugs).includes(nameOf(a)))}
// Limited Chinese name variants and topic phrases from installed Skill descriptions; search only.
const advisorSearchAliases={
 'clear-perspective':'詹姆斯·克利尔 詹姆斯·克里尔 原子习惯 系统的复利力量',
 'andrej-karpathy-perspective':'卡帕西 AI技术可靠性 学习方法 行业趋势 产品设计 神经网络训练 构建即理解',
 'ilya-sutskever-perspective':'伊利亚 苏茨克维 AI技术方向 安全策略 研究品味',
 'paul-graham-perspective':'保罗·格雷厄姆 PG 创业 写作 产品 人生选择',
 'mrbeast-perspective':'野兽先生 内容实验 观众承诺 标题封面一致性 成本取舍 创作复盘',
 'dan-koe-skill':'丹·科 观点定位 技能组合 写作 个人事业 个人成长 创作方向 副业取舍'
};
function normalizeAdvisorSearch(value){return String(value||'').normalize('NFKC').trim().toLowerCase().replace(/[\s·•]+/g,'')}
function advisorTable(){const query=normalizeAdvisorSearch(advisorQuery),ds=domain(selectedDomain),filtered=S.advisors.filter(a=>(!advisorCategory||a.category===advisorCategory)&&(!ds||list(ds.advisor_slugs).includes(nameOf(a)))&&normalizeAdvisorSearch(a.title+' '+nameOf(a)+' '+a.category+' '+(advisorSearchAliases[nameOf(a)]||'')+' '+(a.review_note||'')+' '+advisorDomains(a).map(x=>x.title+' '+x.plan_draft?.title).join(' ')).includes(query));return `<table class="library-table"><thead><tr><th>顾问 / 方法</th><th>可以带着什么问题读</th><th>与我的方向</th><th>原文 / 学习</th></tr></thead><tbody>${filtered.map(a=>{const ad=advisorDomains(a),l=S.learning.find(l=>l.advisor===nameOf(a));return `<tr><td><strong>${esc(a.title)}</strong><small>${esc(a.category)}</small></td><td data-label="用途">${esc(clip(a.review_note||ad[0]?.plan_draft?.approach||'从这个顾问的方法，审视一个具体困惑。',100))}</td><td data-label="关联">${ad.length?ad.map(d=>btn(esc(d.title),'domain:'+d.id,'linkbtn')).join(' / '):'<span class="subtle">可以作为补充视角</span>'}</td><td><div class="actions">${btn(a.installed?(l?'继续读 ↗':'阅读 ↗'):'来源 ↗','advisor:'+nameOf(a),'small')}${l?tag(statuses[l.status]||'有记录'):''}</div></td></tr>`}).join('')}</tbody></table>${filtered.length?'':'<div class="empty">没有匹配的顾问，可以清空筛选，或用知识库查一个具体词。</div>'}`}
function continuedReading(){const all=S.learning.slice(0,5);if(!all.length)return '';return section('接着上次，继续读',btn('查看学习记录','learning-history','linkbtn'))+`<div class="continue-list">${all.map(l=>`<article class="continue-card"><small>${statuses[l.status]||'学习记录'} · ${time(l.updated_at||l.read_at)}</small><h3>${esc(advisor(l.advisor)?.title||l.advisor)}</h3><p>${esc(clip(l.insight||'读到这里，接着往下看。',70))}</p>${btn('继续原文 →','resume:'+l.id,'linkbtn')}</article>`).join('')}</div>`}
async function enterAdvisor(slug,fileId){stashChat();stashReader();close();const a=advisor(slug);if(!a?.installed){open(`<h2>${esc(a?.title||slug)}</h2><p>本机暂未接入此顾问的正文，来源目录保留原项目与许可信息。</p><p>${link(a?.url,'查看来源项目')}</p>`);return}readerInfo=await api('/api/advisor?name='+encodeURIComponent(slug));readerSlug=slug;const ls=list(readerInfo.learning);const old=ls.find(x=>x.status==='reading')||ls[0];const target=fileId||old?.file_id||readerInfo.files?.[0]?.id||'advisor:'+slug;reading=await api('/api/read?id='+encodeURIComponent(target));page='reading';await draw();restoreReadingPosition()}
function restoreReadingPosition(){const draft=readerDraft();if(Number.isFinite(draft?.scrollY)){window.scrollTo({top:draft.scrollY,behavior:'instant'});return}const l=S.learning.find(x=>x.advisor===readerSlug&&x.file_id===reading?.id),body=$('.reader-main');const percent=Number(l?.position)||0;window.scrollTo({top:l?.status==='reading'&&percent>0&&body?body.offsetTop+Math.round(Math.max(0,body.offsetHeight-innerHeight*.8)*percent/100):0,behavior:'instant'})}
function readerDraftKey(){return 'upward-reading-v1:'+dataScope+':'+readerSlug+':'+(reading?.id||'')}
function readerDraft(){try{return JSON.parse(localStorage.getItem(readerDraftKey())||'null')}catch{return null}}
function stashReader(){if(page==='reading'&&reading&&$('#learning-insight'))localStorage.setItem(readerDraftKey(),JSON.stringify({insight:$('#learning-insight').value,goal_id:$('#learning-goal').value,position:Number($('#learning-position').value),scrollY:Math.max(0,Number(window.scrollY)||0)}))}
async function renderReader(){if(!readerInfo||!reading){page='advisors';return draw()}const l=readerDraft()||S.learning.find(l=>l.advisor===readerSlug&&l.file_id===reading.id),files=list(readerInfo.files);$('#view').innerHTML=title(readerInfo.title,'原文、个人理解与运用记录放在一起。',btn('← 回到书房','page:advisors','small'))+`<div class="reader-layout"><nav class="reader-nav" aria-label="阅读资料目录"><h3>资料目录 <small>${files.length} 份</small></h3>${files.map(f=>`<button class="${f.id===reading.id?'selected':''}" data-action="reader-file:${esc(f.id)}">${esc(f.title||f.path)}<small>${esc(f.type||'资料')} · ${f.characters||0} 字符</small></button>`).join('')}<p class="subtle">${link(readerInfo.url,'原始项目')}</p></nav><article class="panel reader-main"><h1>${esc(reading.title)}</h1><div class="read-meta">${esc(reading.kind||'方法资料')} · ${esc(reading.source||readerInfo.title)}${reading.truncated?' · 当前内容已截断':''}</div><div class="markdown">${readingMarkdown(reading.text)}</div></article><aside class="reader-side"><section class="panel"><div class="eyebrow">读完之后，留下自己的理解</div><h3>这对我有什么用？</h3><label for="learning-insight">一个启发，或你准备怎样试一试</label><textarea id="learning-insight" placeholder="结合自己的处境，用自己的话说……">${esc(l?.insight||'')}</textarea><label for="learning-goal">关联一个正在推进的目标</label><select id="learning-goal"><option value="">暂不关联</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${l?.goal_id===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select><label for="learning-position">阅读位置 <span id="position-value">${Number(l?.position)||0}%</span></label><input type="range" id="learning-position" min="0" max="100" value="${Number(l?.position)||0}"><div class="actions">${btn('记录当前位置，下次继续','learning-save:reading','primary')}${btn('我读完了，保存理解','learning-save:read')}${btn('已实际运用，记下结果','learning-save:practiced')}</div></section><section class="panel"><h3>把阅读接到生活</h3><p class="subtle">一份原文可以带去讨论；自己的理解也可以成为下一步行动。</p><div class="actions">${btn('带原文与顾问讨论','reader-chat','primary')}${btn('把理解存成笔记','learning-note')}</div></section></aside></div>`}
function readingMarkdown(text){let raw=String(text||''),out='';const fm=raw.match(/^---\s*\n([\s\S]*?)\n---\s*\n/);if(fm){out+='<details class="source-notes"><summary>原文件说明</summary><pre>'+esc(fm[1])+'</pre></details>';raw=raw.slice(fm[0].length)}const lines=raw.split('\n');let visible=[];const flush=()=>{if(visible.length){out+=markdown(visible.join('\n'));visible=[]}};for(let i=0;i<lines.length;i++){const h=lines[i].match(/^(#{1,6})\s+(.+)$/);if(h&&/^(本地接入约束|角色扮演规则)/.test(h[2])){flush();const block=[lines[i]],level=h[1].length;while(i+1<lines.length){const next=lines[i+1].match(/^(#{1,6})\s+/);if(next&&next[1].length<=level)break;block.push(lines[++i])}out+='<details class="source-notes"><summary>'+(/本地/.test(h[2])?'接入说明 / 原文件':'角色使用说明 / 原文件')+'</summary><pre>'+esc(block.join('\n'))+'</pre></details>'}else visible.push(lines[i])}flush();return out}
function noteCard(n){return `<article class="note"><div class="row spread"><h3>${esc(n.title)}</h3>${tag(statuses[n.index_state]||n.index_state,n.index_state==='indexed'?'good':'')}</div><small>${time(n.created_at)} · ${{idea:'想法',learning:'学习理解',review:'成长复盘',conversation:'对话结论'}[n.kind]||'记录'}${n.goal_id?' · '+esc(S.goals.find(g=>g.id===n.goal_id)?.title||'已关联目标'):''}</small><pre>${esc(n.body)}</pre>${n.index_error?`<p class="error">${esc(n.index_error)}</p>`:''}<div class="actions">${btn('编辑','note:'+n.id,'linkbtn')}${btn('形成行动','record:note:'+n.id,'linkbtn')}${btn('带去讨论','note-chat:'+n.id,'linkbtn')}${btn(n.index_state==='indexed'?'更新知识库':'并入知识库','index:'+n.id,'linkbtn')}${btn('版本','versions:'+n.id,'linkbtn')}${btn(n.archived?'恢复':'归档','archive:'+n.id,'linkbtn')}</div></article>`}
function renderManualReview(v){const g=S.goals.find(g=>g.id===selectedDomain),draft=reviewDraft();v.innerHTML=title('一次复盘，把经历变成下一步。','沿着「主线 → 卡点 → 学什么 → 实际结果 → 下一步」整理，不给生活打分。',btn('返回记录','page:notes','small'))+`<div class="review-layout"><section class="panel"><div class="field"><label for="review-goal">这次围绕哪件事</label><select id="review-goal"><option value="">一次综合复盘</option>${S.goals.map(x=>`<option value="${esc(x.id)}" ${(g?.id||draft.goal_id)===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="review-fields">${[['main','现在的主线','近期真正想推进什么，而不是所有事一起做。'],['obstacle','卡在哪里','描述实际遇到的阻碍，不急着评价自己。'],['learn','这次学到了什么','一段原文、一个顾问观点，或亲身得到的认识。'],['result','实际做了什么，结果如何','留下作品、反馈、变化；还没做，也如实写。'],['next','下一步怎样调整','缩小一步、换一个方法，或先补充一个事实。']].map(([k,h,sub],i)=>`<div class="review-field"><span class="review-number">${i+1}</span><div><label for="review-${k}">${h}<span>${sub}</span></label><textarea id="review-${k}" data-review="${k}">${esc(draft[k]||(k==='main'?g?.title||'':''))}</textarea></div></div>`).join('')}</div><div class="actions actions-spaced">${btn('保存这次复盘','save-review','primary')}${btn('保存并形成行动','save-review-action')}${btn('保存并入知识库','save-review-index')}</div></section><section class="panel"><div class="eyebrow">把真实经历带进来</div><h2>最近的行动与理解</h2>${activeGoals().slice(0,3).map(x=>`<div class="week-item"><strong>${esc(x.title)}</strong><p>${esc(list(x.steps).find(s=>s.outcome)?.outcome||list(x.steps).find(s=>!s.done)?.text||x.why)}</p></div>`).join('')}${S.learning.filter(x=>x.insight).slice(0,3).map(l=>`<div class="week-item"><strong>${esc(advisor(l.advisor)?.title||l.advisor)}</strong><p>${esc(l.insight)}</p></div>`).join('')}${!activeGoals().length&&!S.learning.some(x=>x.insight)?'<p class="muted">可以从今天一件真实的小事开始。没有可量化的结果，也可以记下新发现的问题。</p>':''}</section></div>`}
function renderReview(v){const manual={innerHTML:''};renderManualReview(manual);v.innerHTML=Experience.phaseView(currentPhase(),{days:phaseDays,error:phaseError(),notes:S.notes,question:localStorage.getItem(phaseQuestionKey())||''})+`<details class="manual-review"><summary>想自己整理？打开手动复盘</summary>${manual.innerHTML}</details>`}
function reviewDraft(){try{return JSON.parse(localStorage.getItem('growth-review-draft')||'{}')}catch{return {}}}
function refsHTML(){return selectedRefs.map(r=>`<div class="context-card"><div class="row spread"><strong>${esc(r.title)}</strong>${tag('本轮已选','blue')}</div><div class="actions">${btn('回读原文','read:'+r.id,'linkbtn')}${btn('移除','remove-ref:'+r.id,'linkbtn')}</div></div>`).join('')||'<p class="subtle">尚未额外附上资料。可以直接提问，顾问团会自动选择顾问。</p>'}
function candidatesHTML(){return contextWarnings.map(w=>'<div class="notice">'+esc(w)+'</div>').join('')+contextCandidates.map(r=>`<div class="context-card"><strong>${esc(r.title)}</strong><p>${esc(r.reason||r.excerpt||'相关资料')}</p><div class="actions">${btn('回读','read:'+r.id,'linkbtn')}${btn(selectedRefs.some(x=>x.id===r.id)?'已选入':'选入本轮','select-ref:'+r.id,'linkbtn')}</div></div>`).join('')}
function updateContext(){persistChatState({refs:selectedRefs});const chip=document.querySelector('[data-action="toggle-context"]');if(chip)chip.textContent='资料 · '+selectedRefs.length;if($('#selected-refs'))$('#selected-refs').innerHTML=refsHTML();if($('#context-results'))$('#context-results').innerHTML=candidatesHTML();if($('#context-count'))$('#context-count').textContent=selectedRefs.length;invalidatePreview()}
function invalidatePreview(){if($('#send-preview'))$('#send-preview').innerHTML='<p class="subtle">依据预览未更新。可直接发送最新内容，或重新查看。</p>'}
function draftStoreKey(){return 'upward-chat-v2:'+dataScope}
function chatKey(){return sessionId||draftKey}
function newDraft(){draftKey='draft:'+crypto.randomUUID();sessionId='';selectedRefs=[];selectedDomain='';organizeDraft=true;contextCandidates=[];contextWarnings=[];persistChatState({text:'',refs:[],includeGoals:true,organize:true,useStage:true,stageDays:7,domain:'',model:null});return draftKey}
function loadDraftStore(){try{const stored=JSON.parse(localStorage.getItem(draftStoreKey())||'{}');chatDrafts=stored.drafts||{};const current=stored.current;if(current?.startsWith('draft:'))draftKey=current;else if(current)sessionId=current}catch{chatDrafts={}}if(!chatDrafts[chatKey()])persistChatState({text:'',refs:[],includeGoals:true,organize:true,useStage:true,stageDays:7});}
function currentDraft(key=chatKey()){return chatDrafts[key]||{text:'',refs:[],includeGoals:true,organize:true,useStage:true,stageDays:7,domain:''}}
function saveDraftStore(){localStorage.setItem(draftStoreKey(),JSON.stringify({current:chatKey(),drafts:chatDrafts}))}
function persistChatState(patch={},key=chatKey()){chatDrafts[key]={...currentDraft(key),...patch,updatedAt:Date.now()};saveDraftStore();return chatDrafts[key]}
function stashChat(){if(page!=='chat'||!$('#chat-text'))return;persistChatState({text:$('#chat-text').value,refs:selectedRefs,includeGoals:$('#include-goals')?.checked!==false,organize:$('#organize-reply')?.checked!==false,useStage:$('#include-stage')?.checked!==false,stageDays:currentDraft().stageDays||7,domain:selectedDomain,model:$('#chat-model')?($('#chat-model').value||null):(currentDraft().model||null)})}
function restoreChatState(){const d=currentDraft();selectedRefs=list(d.refs).map(r=>({...r}));selectedDomain=d.domain||'';organizeDraft=d.organize!==false;contextCandidates=[];contextWarnings=[]}
function seedChat(text,refs=[],domainId='',includeGoals=true){stashChat();newDraft();persistChatState({text,refs,domain:domainId,includeGoals});restoreChatState()}
function sessionOptions(){const unsent=Object.entries(chatDrafts).filter(([k,d])=>k.startsWith('draft:')&&(d.text||d.failedText||k===chatKey()));return unsent.map(([k,d])=>`<option value="${esc(k)}" ${k===chatKey()?'selected':''}>草稿 · ${esc(clip(d.text||d.failedText||'新对话',20))}</option>`).join('')+S.sessions.map(s=>`<option value="${esc(s.id)}" ${sessionId===s.id?'selected':''}>${esc(clip(s.title,26))}</option>`).join('')}
function chatNearBottom(box){return box.scrollHeight-box.scrollTop-box.clientHeight<80}
function keepChatBottom(box,follow){box._followLatest=follow;if(follow){box.scrollTop=box.scrollHeight;const notice=$('#new-replies');if(notice)notice.hidden=true}}
function watchChatLayout(){chatResizeObserver?.disconnect();const box=$('#messages');if(!box)return;box._followLatest=true;box.addEventListener?.('scroll',()=>{box._followLatest=chatNearBottom(box)},{passive:true});if(typeof ResizeObserver==='function'){chatResizeObserver=new ResizeObserver(()=>{if(page==='chat'&&$('#messages')===box&&box._followLatest)keepChatBottom(box,true)});chatResizeObserver.observe(box)}}
function renderChat(v){chatEpoch++;chatCursors.delete(sessionId);chatMessagesStamp='';jobStamp='';restoreChatState();const d=currentDraft();v.innerHTML=`<div class="pagetitle chat-title"><div><h1>今天，想聊什么？</h1><p>AI 助理 · 自动选择顾问方法，结合你的问题回答</p></div><div class="row"><select id="session-select" aria-label="选择对话">${sessionOptions()}</select>${btn('＋ 新对话','new-chat','small')}</div></div><div class="chat-layout"><section class="chat-main"><div id="messages" class="chatmessages" aria-label="对话记录"></div><div id="new-replies" class="new-replies" hidden>${btn('有新回复 · 查看最新 ↓','latest-messages','small')}</div><div id="job-state" aria-live="polite"></div><div class="composer"><div id="chat-error" role="alert"></div>${localStorage.getItem('growth-chat-draft')&&!localStorage.getItem('upward-legacy-restored:'+dataScope)?'<div class="legacy-draft">发现旧版未发送草稿。'+btn('恢复为独立草稿','restore-legacy','linkbtn')+'</div>':''}<label class="sr-only" for="chat-text">给 AI 顾问团的消息</label><textarea id="chat-text" placeholder="说目标、聊卡点，或告诉我今天完成了什么…">${esc(d.text)}</textarea><div class="composer-options"><span class="composer-chip">✦ 自动顾问团</span><label><input type="checkbox" id="include-stage" ${d.useStage!==false?'checked':''} title="携带这个期间的想法、行动学习、创作留底及已接入的方法原文">近 ${d.stageDays||7} 天阶段与方法</label><label><input type="checkbox" id="include-goals" ${d.includeGoals!==false?'checked':''}>进行中与暂停目标 ${S.goals.filter(g=>['active','paused'].includes(g.status)).length} 项</label><label><input type="checkbox" id="organize-reply" ${d.organize!==false?'checked':''}>整理目标与记录</label>${btn('资料 · '+selectedRefs.length,'toggle-context','linkbtn')}</div><div id="model-control">${modelSelectorHTML()}</div><div class="actions"><small>Enter 发送 · Shift + Enter 换行</small><div class="row">${btn('查看发送依据','preview','linkbtn')}${btn('发送 ↑','send-direct','primary')}</div></div></div><details class="chat-context"><summary>补充资料与发送依据 · <span id="context-count">${selectedRefs.length}</span> 份资料</summary><div class="context-inner"><p class="subtle">顾问团自动从全库选择方法。可补充个人材料；未附上的私人资料不会因此被扫描。两次模型调用：选择顾问、结合方法回答。</p><p class="subtle">勾选阶段时，会带入所选期间的本人想法、当前目标、行动与学习记录、创作留底，以及已连接的「让我伟大」方法原文。实际来源与截取范围可在发送依据中核对；不会因此扫描其他私档。</p><div class="toolbar"><input id="context-query" aria-label="搜索本轮资料" placeholder="搜索需要补充的资料">${btn('查找','context-search','small')}</div><div id="selected-refs">${refsHTML()}</div><div id="context-results">${candidatesHTML()}</div><div id="send-preview" class="context-preview"><p class="subtle">可以直接发送；需要核对本轮问题、资料或历史时，再查看发送依据。</p></div></div></details></section></div>`;watchChatLayout();renderChatFailure();updateSendButton();void loadModels()}
function renderChatFailure(){const el=$('#chat-error');if(!el)return;const d=currentDraft();el.innerHTML=d.sendError?`<div class="chat-send-error"><span>${esc(d.sendError)}</span>${d.failedText?btn('恢复未发送的内容','restore-failed','linkbtn'):''}${d.pending?.previewId?btn('核对并重试本次发送','retry-send','linkbtn'):''}</div>`:''}
function currentJob(){return chatJobs.get(sessionId)||S.jobs.find(j=>j.session_id===sessionId)}
function isJobRunning(j){return !!j&&['queued','running','cancelling'].includes(j.status)}
function updateSendButton(){const b=document.querySelector('[data-action="send-direct"]');if(!b)return;const busy=chatBusy.has(chatKey()),running=isJobRunning(currentJob());b.disabled=busy||running||(!currentDraft().text?.trim()&&!currentDraft().pending?.previewId);b.textContent=busy?'正在发送…':running?'回复中 · 可继续写':'发送 ↑'}
function chatSnapshot(){stashChat();const d=currentDraft();return {message:d.text,session_id:sessionId||null,refs:list(d.refs).map(r=>r.id),include_goals:d.includeGoals!==false,organize:d.organize!==false,include_stage:d.useStage!==false,stage_days:d.stageDays||7,intent:d.intent||'discussion',model:d.model||null}}
async function sendChat(previewId=null,retry=false){const key=chatKey();if(chatBusy.has(key)||isJobRunning(currentJob()))return;const saved=currentDraft();if(saved.pending?.previewId&&!retry){stashChat();persistChatState({sendError:'上次发送结果尚未确认。请先核对并重试原请求；新问题保留在输入框，不会替你发送旧问题。'});renderChatFailure();return}const snapshot=retry?saved.pending?.snapshot:chatSnapshot();if(!snapshot?.message?.trim()){persistChatState({sendError:'先写下一句话，再发送。'});renderChatFailure();return}chatBusy.add(key);const nextText=retry&&saved.text!==snapshot.message?saved.text:'';persistChatState({text:nextText,sendError:'',failedText:'',pending:{snapshot,previewId:previewId||(retry?saved.pending?.previewId:null)||null}},key);if(page==='chat'&&chatKey()===key){$('#chat-text').value=nextText;renderChatFailure();updateSendButton()}let pid=previewId||(retry?saved.pending?.previewId:null);try{if(!pid){const p=await api('/api/chat/preview',snapshot);pid=p.id;persistChatState({pending:{snapshot,previewId:pid}},key)}const r=await api('/api/chat/send',{preview_id:pid});const continuation=currentDraft(key);persistChatState({...continuation,pending:null,sendError:'',failedText:''},r.session_id);if(key!==r.session_id)delete chatDrafts[key];const wasCurrent=chatKey()===key;if(wasCurrent){sessionId=r.session_id;restoreChatState()}if(!S.sessions.some(s=>s.id===r.session_id))S.sessions.unshift({id:r.session_id,title:snapshot.message});chatJobs.set(r.session_id,{...r,message:snapshot.message,status:r.status||'queued'});saveDraftStore();if(wasCurrent&&page==='chat'){$('#session-select').innerHTML=sessionOptions();await loadMessages()}else toast('消息已发送到原会话。')}catch(e){const now=currentDraft(key);persistChatState({text:now.text||snapshot.message,failedText:now.text&&now.text!==snapshot.message?snapshot.message:'',sendError:e.message,pending:pid?{snapshot,previewId:pid}:null},key);if(chatKey()===key&&page==='chat'){if(!$('#chat-text').value)$('#chat-text').value=currentDraft(key).text;renderChatFailure()}}finally{chatBusy.delete(key);if(page==='chat')updateSendButton()}}
function messageHTML(m){return `<label>${m.role==='user'?'我':'AI 顾问团'} · ${time(m.created_at)}</label>${m.role==='assistant'?Experience.processSummary(m.reply_context):''}<div class="markdown">${markdown(m.text)}</div>${m.role==='assistant'?replyEvidence(m)+`<div class="actions">${btn('保存结论','save-message:'+m.id,'linkbtn')}${btn('形成目标或行动','record:message:'+m.id,'linkbtn')}</div>`:''}`}
function renderMessages(messages,box){const stamp=JSON.stringify(messages);if(stamp===chatMessagesStamp)return;const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<80,scroll=box.scrollTop;chatMessagesStamp=stamp;if(!messages.length){box.innerHTML=`<div class="chatwelcome"><div class="eyebrow">在自己的书桌前，慢慢想清楚</div><h2>从真实处境，聊到下一步。</h2><p>顾问方法自动选择；目标和记录按你的原话整理。</p><div class="chat-starters">${[['我想理清现在最值得推进的一件事','理清当下重点'],['我今天完成了一些事，想做个简短复盘','回顾今天'],['我有个卡点，想听听不同顾问的方法','拆解一个卡点']].map(([text,label])=>btn(label,'starter:'+text,'suggestion')).join('')}</div></div>`;return}if(box.querySelector('.chatwelcome'))box.innerHTML='';const wanted=new Set();for(const m of messages){const id=String(m.id);wanted.add(id);let node=[...box.children].find(n=>n.dataset.messageId===id);if(!node){node=document.createElement('article');node.dataset.messageId=id;node.className='message '+(m.role==='user'?'user':'assistant');box.append(node)}const html=messageHTML(m);if(node._rendered!==html){const expanded=[...node.querySelectorAll('details')].map((d,i)=>d.open?i:-1).filter(i=>i>=0);node.innerHTML=html;node._rendered=html;expanded.forEach(i=>{const d=node.querySelectorAll('details')[i];if(d)d.open=true})}}for(const child of [...box.children])if(!child.dataset.liveProcess&&!wanted.has(child.dataset.messageId))child.remove();if(nearBottom){box.scrollTop=box.scrollHeight;if($('#new-replies'))$('#new-replies').hidden=true}else{box.scrollTop=scroll;if($('#new-replies'))$('#new-replies').hidden=false}}
function renderLiveProcess(job){const box=$('#messages');if(!box)return;let node=[...box.children].find(n=>n.dataset.liveProcess);const show=job&&(isJobRunning(job)||!lastMessages.some(m=>m.role==='assistant'&&m.job_id===job.id));const html=show?Experience.processSummary(job,{live:isJobRunning(job)}):'';if(!html){node?.remove();return}if(!node){node=document.createElement('aside');node.dataset.liveProcess='true';node.className='live-process';box.append(node)}if(node._rendered!==html){const opened=[...node.querySelectorAll('details')].map((d,i)=>d.open?i:-1).filter(i=>i>=0);node.innerHTML=html;node._rendered=html;opened.forEach(i=>{const d=node.querySelectorAll('details')[i];if(d)d.open=true})}}
function renderJob(job){renderLiveProcess(job);const el=$('#job-state');if(!el)return;const stamp=JSON.stringify([job||null,jobCaptureHTML(job)]);if(stamp!==jobStamp){jobStamp=stamp;const open=el.querySelector('details')?.open;const phases={local:'正在执行本轮本地操作',selecting:'正在选择顾问',reading:'正在读取技能',answering:'顾问方法分析中'};el.innerHTML=job?`<div class="job-line ${['failed','interrupted'].includes(job.status)?'error':''}"><span>${esc(isJobRunning(job)?phases[job.council_phase]||statuses[job.status]||job.status:statuses[job.status]||job.status)}</span><small id="job-elapsed"></small>${isJobRunning(job)?btn('停止','cancel:'+job.id,'linkbtn'):['failed','interrupted','cancelled'].includes(job.status)?btn('恢复问题','retry:'+job.id,'linkbtn'):''}</div>${job.error?'<p class="chat-job-error">'+esc(job.error)+'</p>':''}${!isJobRunning(job)&&!lastMessages.some(m=>m.role==='assistant'&&m.job_id===job.id)&&job.advisor_selection?.length?'<details class="job-details"><summary>本轮顾问与依据</summary>'+jobCouncilHTML(job)+'</details>':''}${jobCaptureHTML(job)}`:'';if(open&&el.querySelector('details'))el.querySelector('details').open=true}const duration=$('#job-elapsed'),start=Date.parse(job?.created_at||job?.started_at||'');if(duration)duration.textContent=isJobRunning(job)&&Number.isFinite(start)?'已等待 '+Math.max(0,Math.floor((Date.now()-start)/1000))+' 秒'+(Date.now()-start>60000?' · 可以先做别的，回复会留在这里':''):'';updateSendButton()}
async function loadMessages(){if(page!=='chat'||document.visibilityState==='hidden')return;clearTimeout(poll);const sid=sessionId,epoch=chatEpoch,request=++chatRequestSerial;try{const r=sid?await api('/api/chat/status?session_id='+encodeURIComponent(sid)+'&after='+encodeURIComponent(chatCursors.get(sid)||'')):{messages:[],job:null};if(page!=='chat'||sessionId!==sid||epoch!==chatEpoch||request!==chatRequestSerial)return;if(r.cursor)chatCursors.set(sid,r.cursor);if(r.messages)lastMessages=r.messages;if(r.job)chatJobs.set(sid,r.job);if(r.sessions)S.sessions=r.sessions;const box=$('#messages');if(!box)return;const followLatest=!chatMessagesStamp||chatNearBottom(box);renderMessages(lastMessages,box);const job=r.job||null;renderJob(job);keepChatBottom(box,followLatest);if(job&&(isJobRunning(job)||['pending','organizing'].includes(job.capture_status)||list(job.capture_receipt?.saved_items).some(x=>x.index_state==='indexing')))poll=setTimeout(()=>loadMessages(),1000);else if(job){const refreshKey=JSON.stringify([job.id,job.capture_status,job.capture_receipt]);if(!completedRefresh.has(refreshKey)){await refresh(false);completedRefresh.add(refreshKey);if(page==='chat'&&sessionId===sid&&epoch===chatEpoch&&request===chatRequestSerial){const followAfterSync=chatNearBottom(box);jobStamp='';renderJob(job);keepChatBottom(box,followAfterSync)}}}}catch(e){if(page!=='chat'||sessionId!==sid||epoch!==chatEpoch||request!==chatRequestSerial)return;const el=$('#job-state');if(el)el.innerHTML='<p class="chat-job-error">连接暂时中断，输入仍保留。正在重新连接…</p>';poll=setTimeout(()=>loadMessages(),5000)}}

function replyEvidence(m){const c=m.reply_context;if(!c)return '<details class="reply-evidence"><summary>当轮依据与发送内容</summary><p class="subtle">这条历史回复没有保存可回读的发送快照，不用当前资料替代历史依据。</p></details>';return `<details class="reply-evidence"><summary>当轮依据与发送内容 · ${list(c.contexts).length} 份资料</summary><p class="subtle">这是当时实际发送的快照。右侧资料属于下一轮选择，修改后不会改变此处留底。</p>${c.message?'<div class="context-card"><strong>当轮问题</strong><pre>'+esc(c.message)+'</pre></div>':''}${list(c.advisor_selection).length?'<section class="council-evidence"><strong>本轮实际选中的顾问</strong>'+councilSelectionHTML(c.advisor_selection)+'</section>':''}${c.advisor_catalog_count!==undefined?'<p class="subtle">当轮可调度目录：'+(Number(c.advisor_catalog_count)||0)+' 位。目录数量不代表全部已读；下方仅展示实际纳入回答的正文快照。</p>':''}<p class="subtle">当轮携带 ${Number(c.history_count)||0} 条历史</p>${list(c.contexts).map(r=>`<details><summary>${esc(r.title)} · ${esc(r.kind||'资料')}${r.truncated?' · 截取内容':''}</summary><pre class="reading">${esc(r.text)}</pre><small>实际包含 ${Number(r.included_characters)||String(r.text||'').length} 字符${r.sha256?'<br>正文 SHA-256：'+esc(r.sha256):''}</small></details>`).join('')}${list(c.history).length?`<details><summary>当轮历史正文</summary><pre class="reading">${esc(c.history.map(x=>x.role+'：'+x.text).join('\n\n'))}</pre></details>`:''}<details><summary>快照标识</summary><small>预览 ${esc(c.preview_id||'')}<br>内容校验 ${esc(c.context_hash||'')}</small></details></details>`}
function domainDetail(d){open(`<div class="eyebrow">${esc(d.title)} · 从资料整理的方案</div><h2>${esc(d.plan_draft?.title||d.title)}</h2><p>${esc(d.plan_draft?.why||d.priority_reason)}</p><div class="muted-box">${esc(plain(d.plan_draft?.approach)||d.priority_reason)}</div><h3 class="subsection-title">这些判断，来自你的材料</h3>${list(d.known_facts).map(f=>`<div class="evidence-item"><p>${esc(f.text)}</p><small>${esc(f.date||'日期见原文')} · ${esc(f.evidence_type||'材料记录')} · ${esc(f.locator||'')}</small><div>${btn('回读：'+esc(sourceTitle(f.source_id)),'read:source:'+String(f.source_id||'').replace(/^source:/,''),'linkbtn')}</div></div>`).join('')}${list(d.constraints).length?`<h3>需要一起考虑的现实条件</h3><ul>${list(d.constraints).map(x=>'<li>'+esc(plain(x))+'</li>').join('')}</ul>`:''}${list(d.unknowns).length?`<details><summary>还需要补充 ${list(d.unknowns).length} 项信息</summary><ul>${list(d.unknowns).map(x=>'<li>'+esc(plain(x))+'</li>').join('')}</ul></details>`:''}<h3>可选的起步行动</h3>${list(d.actions).map(a=>`<div class="week-item"><strong>${esc(a.title)}</strong><p>${list(a.steps).map(plain).map(esc).join(' → ')}</p><small>完成依据：${esc(plain(a.completion_evidence)||'留下实际结果')}</small></div>`).join('')}<p class="subtle">回看时机：${esc(d.plan_draft?.review_trigger||'行动完成，或现实条件改变时')}</p><div class="actions">${btn('采用并调整这套方案','adopt:'+d.id,'primary')}${btn('先和顾问讨论','domain-chat:'+d.id)}${btn('回读完整方案','read:plan:'+d.id,'linkbtn')}</div>`,true)}
function adoptionForm(d,onlyActionId){adoptDomain=d;const old=activeGoals().find(g=>g.domain_id===d.id);if(old){goalForm(old);return}const steps=list(d.actions).map(a=>({text:a.title,criterion:plain(a.completion_evidence)||'',due:a.due||''}));open(`<div class="eyebrow">${esc(d.title)} · 由你决定开始</div><h2>把整理好的方案，变成自己的计划。</h2><p class="subtle">内容已按你的材料填写。采用后保存为工作台执行目标；原目标台账保持只读，采用状态不会自动写回。</p><div class="field"><label for="adopt-title">这个阶段要做到什么</label><input id="adopt-title" value="${esc(d.plan_draft?.title||d.title)}"></div><div class="field"><label for="adopt-why">为什么值得做</label><textarea id="adopt-why">${esc(d.plan_draft?.why||d.priority_reason)}</textarea></div><div class="formrow"><div class="field"><label for="adopt-priority">当前优先级</label><select id="adopt-priority"><option value="1">优先推进</option><option value="2" selected>稳步推进</option><option value="3">有余力时推进</option></select></div><div class="field"><label for="adopt-due">阶段回看日期（可留空）</label><input type="date" id="adopt-due"></div></div><h3>起步行动，可以删减</h3><div id="adopt-actions">${steps.map((s,i)=>`<div class="evidence-item"><label class="step"><input type="checkbox" data-adopt-check="${i}" ${!onlyActionId||list(d.actions)[i]?.id===onlyActionId?'checked':''}>采用这一步</label><input data-adopt-text="${i}" aria-label="行动 ${i+1}" value="${esc(s.text)}"><div class="field"><label>怎样算做到</label><input data-adopt-criterion="${i}" value="${esc(s.criterion)}"></div><label class="subtle">准备在哪天做</label><input type="date" data-adopt-due="${i}" value="${esc(s.due)}"></div>`).join('')}</div><div class="actions">${btn('确认采用，加入我的计划','save-adopt','primary')}${btn('暂时不采用','close','quiet')}</div>`,true)}
function editedSteps(lines,oldSteps){
 const used=new Set(),matches=lines.map(text=>{const found=oldSteps.find(x=>x.text===text&&!used.has(x.id));if(found)used.add(found.id);return found});
 return lines.map((text,i)=>{if(matches[i])return {...matches[i],text};const prior=oldSteps[i];if(prior&&!used.has(prior.id)){used.add(prior.id);return {...prior,text}}return {text,done:false}});
}
function goalForm(g){goalEditBase=g?.id?structuredClone(g):null;g=g||{status:'active',steps:[],title:'',why:'',due:'',domain:'个人目标'};open(`<div class="eyebrow">目标与计划</div><h2>${g.id?'调整目标，保留过程':'自定一个当前目标'}</h2><p class="subtle">新目标保存后即加入正在推进；日期可以不填。想暂存时，可把状态改为草稿。</p><div class="field"><label for="g-title">我想实现什么</label><input id="g-title" value="${esc(g.title)}"></div><div class="field"><label for="g-why">为什么值得做</label><textarea id="g-why">${esc(g.why)}</textarea></div><div class="formrow"><div class="field"><label for="g-domain">所属方向</label><select id="g-domain"><option value="">个人自定</option>${domains().map(d=>`<option value="${esc(d.id)}" ${g.domain_id===d.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select></div><div class="field"><label for="g-due">目标日期</label><input type="date" id="g-due" value="${esc(g.due||'')}"></div></div><div class="formrow"><div class="field"><label for="g-status">当前状态</label><select id="g-status">${['draft','active','paused','done','archived'].map(s=>`<option value="${s}" ${g.status===s?'selected':''}>${statuses[s]}</option>`).join('')}</select></div><div class="field"><label for="g-priority">当前优先级</label><select id="g-priority">${[[1,'优先推进'],[2,'稳步推进'],[3,'有余力时推进']].map(([v,t])=>`<option value="${v}" ${(g.priority||2)===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label for="g-parent">连接一个长期目标</label><select id="g-parent"><option value="">独立方向</option>${S.goals.filter(x=>x.id!==g.id).map(x=>`<option value="${esc(x.id)}" ${g.parent_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label for="g-steps">接下来做什么（每行一个行动）</label><small>修改原行动标题会保留结果；新增行动请另起一行。</small><textarea id="g-steps">${esc(list(g.steps).map(s=>s.text).join('\n'))}</textarea></div><div class="field"><label for="g-evidence">实际结果与证据（完成目标时填写）</label><textarea id="g-evidence">${esc(g.evidence||'')}</textarea></div>${recordOrigin(g.origin_id)}${g.source_snapshot?'<details><summary>方案来源与采用记录</summary><pre class="reading">'+esc(JSON.stringify(g.source_snapshot,null,2))+'</pre><p class="subtle">保存为工作台执行目标；原目标台账保持只读，采用状态未写回原台账。</p></details>':''}${btn('保存目标','save-goal:'+(g.id||'new'),'primary')}`)}
function noteForm(n){noteEditBase=n?.id?structuredClone(n):null;open(`<div class="eyebrow">保留原话，再继续整理</div><h2>${n?.id?'编辑这条记录':'留下一条记录'}</h2><div class="field"><label for="n-title">标题</label><input id="n-title" value="${esc(n?.title||'')}"></div><div class="field"><label for="n-body">内容</label><textarea id="n-body" class="note-editor">${esc(n?.body||'')}</textarea></div><div class="formrow"><div class="field"><label for="n-kind">记录类型</label><select id="n-kind">${[['idea','想法'],['learning','学习理解'],['review','复盘'],['conversation','对话结论']].map(([k,t])=>`<option value="${k}" ${n?.kind===k?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="n-goal">关联目标</label><select id="n-goal"><option value="">暂不关联</option>${S.goals.map(g=>`<option value="${esc(g.id)}" ${n?.goal_id===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select></div></div><div class="actions">${btn('保存记录','save-note:'+(n?.id||'new'),'primary')}${btn('保存并入知识库','save-index-note:'+(n?.id||'new'))}</div>`)}
function recordDraft(body,title){const text=String(body||'').replace(/\r/g,''),parts=text.split('\n');const next=text.match(/(?:^|\n)#{1,6}\s*(?:下一步|行动计划|行动建议|具体行动|接下来)[^\n]*\n([\s\S]*?)(?=\n#{1,6}\s|$)/);const scope=(next?.[1]||text).split('\n').map(s=>s.trim()).filter(Boolean);const clean=s=>s.replace(/^#{1,6}\s*/,'').replace(/^[-*+]\s+|^\d+[.)、]\s*/,'').replace(/\*\*/g,'').trim();let steps=scope.filter(s=>/^[-*+]\s+|^\d+[.)、]\s*/.test(s)).map(clean);if(!next)steps=steps.filter(s=>/(整理|选择|列出|检查|确认|记录|完成|阅读|练习|写下|回看|核对|尝试|比较|做一次|找出|开始|制定|联系|保存|安排|停止|复盘|检验|收集|更新)/.test(s));if(next&&!steps.length)steps=scope.filter(s=>!/^#/.test(s)).map(clean);steps=steps.filter(s=>s&&s!=='暂未记录').slice(0,5);const first=steps[0]||parts.map(clean).find(s=>s&&s!=='暂未记录')||'';return {title:clip(next?first:title||first,90),why:clip(parts.map(clean).filter(s=>s&&!/^(主线|卡点|学什么|实际结果|下一步)$/.test(s)).join('；'),260),steps}}
function recordForm(sourceId){recordSource=sourceId;const [kind,id]=sourceId.split(':');const src=kind==='message'?lastMessages.find(m=>m.id===id):S.notes.find(n=>n.id===id);const body=src?.text||src?.body||'',draft=recordDraft(body,src?.title);open(`<div class="eyebrow">从讨论与经历，走向行动</div><h2>把值得做的部分，留下来推进。</h2><p class="notice">按原文整理的可编辑草稿，请核对取舍；尚未自动承诺。${draft.steps.length?'':'原文未识别到明确行动，已保留结论，请补充你愿意推进的一步。'}</p><details><summary>回看这条${kind==='message'?'回复':'记录'}</summary><div class="markdown">${markdown(body)}</div></details><div class="field"><label for="record-mode">这次怎样推进</label><select id="record-mode"><option value="goal">形成一个新目标</option>${S.goals.length?'<option value="action">添加到已有目标，作为下一步行动</option>':''}</select></div><div class="field" id="record-existing" hidden><label for="record-goal">关联目标</label><select id="record-goal">${S.goals.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select></div><div class="field"><label for="record-title">我愿意推进的这件事</label><input id="record-title" value="${esc(draft.title)}" placeholder="从原文中取舍，用一句话说清楚"></div><div class="field"><label for="record-why">意义 / 完成依据</label><textarea id="record-why" placeholder="怎样才算真的有进展？">${esc(draft.why)}</textarea></div><div id="record-goal-fields"><div class="field"><label for="record-steps">起步行动（每行一个）</label><textarea id="record-steps">${esc(draft.steps.join('\n'))}</textarea></div><div class="field"><label for="record-domain">所属方向</label><select id="record-domain"><option value="">个人自定</option>${domains().map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></div></div><div class="formrow"><div class="field"><label for="record-due">准备在哪天做（可留空）</label><input type="date" id="record-due"></div><div class="field"><label for="record-priority">当前优先级</label><select id="record-priority"><option value="1">优先推进</option><option value="2" selected>稳步推进</option><option value="3">有余力时推进</option></select></div></div>${btn('确认，加入我的计划','save-record','primary')}<p class="subtle">这次确认会留下来源关联；不会把整条回复自动当作承诺。</p>`,true)}
async function showRead(id){reading=await api('/api/read?id='+encodeURIComponent(id));open(`<div class="eyebrow">${esc(reading.kind||'原始材料')}</div><h2>${esc(reading.title)}</h2><p class="subtle">${esc(reading.source||'')}${reading.truncated?' · 当前显示内容已截断':''}</p><div class="markdown">${markdown(reading.text)}</div><div class="actions actions-spaced">${btn('选入本轮对话','read-chat','primary')}${btn('关闭','close')}</div>`,true)}
async function requestContext(question){const key=chatKey();if(!question.trim())throw Error('先说出一个具体问题，我再帮你找资料。');const r=await api('/api/context',{question,domain_id:domain(selectedDomain)?selectedDomain:undefined});if(page!=='chat'||chatKey()!==key)return r;contextCandidates=r.candidates||[];contextWarnings=r.warnings||[];if(!contextCandidates.length&&!contextWarnings.length)contextWarnings=['没有找到足够相关的资料。可以换一个具体词，或直接讨论。'];for(const id of r.suggested_ids||[]){const c=contextCandidates.find(x=>x.id===id);if(c&&selectedRefs.length<4)addRef(c)}updateContext();return r}
function draftId(body){let x;try{x=JSON.parse(localStorage.getItem('growth-save-request')||'null')}catch{}if(!x||x.body!==body){x={body,id:crypto.randomUUID()};localStorage.setItem('growth-save-request',JSON.stringify(x))}return x.id}
async function watchIndex(){if(indexWatch)return indexWatch;indexWatch=(async()=>{for(let i=0;i<20;i++){const pending=S.notes.filter(n=>n.index_state==='indexing');if(!pending.length)break;await new Promise(r=>setTimeout(r,1500));const updates=await Promise.all(pending.map(n=>api('/api/note/status?id='+encodeURIComponent(n.id))));for(const update of updates){const note=S.notes.find(n=>n.id===update.id);if(note)Object.assign(note,update)}if(!S.notes.some(n=>n.index_state==='indexing'))break}await refresh(false);if(page==='notes'&&backgroundCanDraw())await draw()})().finally(()=>{indexWatch=null});return indexWatch}
async function action(a){if(a==='models-stop'){modelCheckState=await api('/api/models/check/stop',{});repaintModels();return}if(a==='models-check'){await checkModelConnections();return}if(a==='models-refresh'){await loadModels(true,true);return}const [cmd,...rest]=a.split(':'),id=rest.join(':');
if(cmd==='page')await navigate(id);
else if(cmd==='close')close();
else if(cmd==='quick-note'){noteSeed=null;noteForm(null)}
else if(cmd==='domain')domainDetail(domain(id));
else if(cmd==='adopt'){const [did,aid]=id.split(':');adoptionForm(domain(did),aid)}
else if(cmd==='save-adopt'){const steps=[...document.querySelectorAll('[data-adopt-check]')].filter(x=>x.checked).map(x=>{const i=x.dataset.adoptCheck,original=list(adoptDomain.actions)[Number(i)];return {plan_action_id:original?.id,canonical_action_ref:original?.canonical_action_ref||'',text:$(`[data-adopt-text="${i}"]`).value,criterion:$(`[data-adopt-criterion="${i}"]`).value,due:$(`[data-adopt-due="${i}"]`).value,done:false}});await api('/api/adopt',{domain_id:adoptDomain.id,title:$('#adopt-title').value,why:$('#adopt-why').value,priority:Number($('#adopt-priority').value),due:$('#adopt-due').value,steps});close();page='goals';await refresh();toast('已采用，接下来按你的节奏推进。')}
else if(cmd==='domain-chat'||cmd==='domain-question'){const d=domain(id);selectedDomain=d.id;seedChat(`请结合我的资料和顾问方法，帮我讨论「${d.plan_draft?.title||d.title}」。\n${d.plan_draft?.first_question||'先识别当前最关键的卡点，再一起取舍一个能验证的下一步。'}`,[],d.id);close();page='chat';await draw();await requestContext($('#chat-text').value)}
else if(cmd==='panorama-discuss'){const p=S.plan?.life_panorama,m=p?.mastery;if(!m)throw Error('尚未接入近期专精方法');const refs=[...new Set([...list(m.source_id),...list(list(p.route)[0]?.source_ids)])].filter(Boolean).slice(0,4).map(sid=>({id:'source:'+String(sid).replace(/^source:/,''),title:sourceTitle(sid)}));seedChat(`请按我已有的「${m.title||'让我伟大'}」方法，结合当前材料，复盘近期工作如何更专精。\n${list(m.steps).map((x,i)=>`${i+1}. ${x.title}：${x.description}`).join('\n')}\n请先区分本人意愿、当前事实、历史记录和待验证判断。缺少当前成果证据时写明未知，不复用旧进度或收入数字，不自动替我承诺新的行动。\n${m.boundary||''}`,refs);close();page='chat';await draw()}
else if(cmd==='goal-chat'){const intent=($('#goal-intent')?.value||'').trim();if(intent){seedChat(intent,[],'');localStorage.removeItem('growth-goal-intent')}const key=chatKey();await navigate('chat');if(page==='chat'&&chatKey()===key){$('#chat-text')?.focus();if(intent)await sendChat()}}
else if(cmd==='locate-goal')document.getElementById('goal-'+id)?.scrollIntoView({behavior:'smooth',block:'center'});
else if(cmd==='dismiss-receipt'){saveReceipt=null;await draw()}
else if(cmd==='activate-goal'){const g=S.goals.find(g=>g.id===id);if(!g)throw Error('目标已变化，请刷新后查看。');const saved=await api('/api/goals',{...g,status:'active'});await finishGoalSave(saved)}
else if(cmd==='goal')goalForm(S.goals.find(g=>g.id===id));
else if(cmd==='save-goal'){const old=goalEditBase?.id===id?goalEditBase:S.goals.find(g=>g.id===id),lines=$('#g-steps').value.split('\n').map(x=>x.trim()).filter(Boolean),did=$('#g-domain').value;const saved=await api('/api/goals',{...old,title:$('#g-title').value,why:$('#g-why').value,parent_id:$('#g-parent').value,domain_id:did,domain:domain(did)?.title||'个人自定',due:$('#g-due').value,status:$('#g-status').value,priority:Number($('#g-priority').value),evidence:$('#g-evidence').value,steps:editedSteps(lines,old?.steps||[])});await finishGoalSave(saved)}
else if(cmd==='activate-step'){const [gid,sid]=id.split(':'),g=structuredClone(S.goals.find(g=>g.id===gid)),step=g.steps.find(s=>s.id===sid);if(!step)throw Error('行动已变化，请重新读取。');step.status='active';step.done=false;const saved=await api('/api/goals',g);await finishGoalSave(saved)}
else if(cmd==='step'){const [gid,sid]=id.split(':');stepEditBase=structuredClone(S.goals.find(g=>g.id===gid));const s=stepEditBase.steps.find(s=>s.id===sid);open(`<div class="eyebrow">一个具体行动</div><h2>${esc(s.text)}</h2><div class="field"><label for="step-due">准备在哪天做</label><input type="date" id="step-due" value="${esc(s.due||'')}"></div><div class="field"><label for="step-criterion">怎样算做到了</label><textarea id="step-criterion">${esc(s.criterion||'')}</textarea></div><div class="field"><label for="step-outcome">实际结果或证据</label><textarea id="step-outcome">${esc(s.outcome||'')}</textarea></div><label class="step"><input id="step-done" type="checkbox" ${s.done?'checked':''}>这一步已经完成</label>${btn('保存行动安排','save-step:'+id,'primary')}`)}
else if(cmd==='save-step'){const [gid,sid]=id.split(':'),g=structuredClone(stepEditBase?.id===gid?stepEditBase:S.goals.find(g=>g.id===gid)),s=g.steps.find(s=>s.id===sid);Object.assign(s,{due:$('#step-due').value,criterion:$('#step-criterion').value,outcome:$('#step-outcome').value,done:$('#step-done').checked});await api('/api/goals',g);close();await refresh();toast('行动和结果已保存。')}
else if(cmd==='discuss-goal'){const g=S.goals.find(g=>g.id===id);selectedDomain=g.domain_id||'';seedChat(`我想讨论正在推进的目标：${g.title}\n请先帮我找出当前卡点，再讨论下一步。`);close();page='chat';await draw();$('#include-goals').checked=true;await requestContext($('#chat-text').value)}
else if(cmd==='capture-save'||cmd==='capture-index'){const b=$('#capture').value;if(!b.trim())throw Error('先留下一句想法。');await api('/api/notes',{body:b,kind:'idea',index:cmd==='capture-index',request_id:draftId(b)});localStorage.removeItem('growth-draft');localStorage.removeItem('growth-save-request');await refresh();toast(cmd==='capture-index'?'想法已保存，正在并入知识库。':'想法已保存。');if(cmd==='capture-index')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='capture-chat'){seedChat($('#capture').value);await navigate('chat')}
else if(cmd==='toggle-archive'){showArchived=!showArchived;await draw()}
else if(cmd==='archive'){const n=S.notes.find(n=>n.id===id);await api('/api/note/archive',{id,archived:!n.archived});await refresh();toast(n.archived?'记录已恢复。':'已归档，原文与版本仍然保留。')}
else if(cmd==='note'){noteSeed=null;noteForm(S.notes.find(n=>n.id===id))}
else if(cmd==='save-note'||cmd==='save-index-note'){const old=noteEditBase?.id===id?noteEditBase:S.notes.find(n=>n.id===id);await api('/api/notes',{...old,...(!old?noteSeed||{}:{}),title:$('#n-title').value,body:$('#n-body').value,kind:$('#n-kind').value,goal_id:$('#n-goal').value,index:cmd==='save-index-note',request_id:!old?draftId($('#n-body').value):undefined});close();noteSeed=null;await refresh();toast(cmd==='save-index-note'?'记录已保存，正在入库。':'记录已保存。');if(cmd==='save-index-note')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='index'){await api('/api/index',{id});await refresh();toast('正在并入知识库，完成后更新状态。');watchIndex().catch(e=>toast(e.message))}
else if(cmd==='versions'){const r=await api('/api/versions?id='+encodeURIComponent(id));open('<h2>这条记录的变化</h2>'+r.versions.map(v=>`<details><summary>版本 ${v.rev} · ${time(v.data.updated_at)}</summary><pre class="reading">${esc(v.data.body||JSON.stringify(v.data,null,2))}</pre></details>`).join(''))}
else if(cmd==='note-chat'){const n=S.notes.find(n=>n.id===id);seedChat('我想接着这条记录讨论：'+n.title,[{id:'note:'+id,title:n.title}]);await navigate('chat')}
else if(cmd==='review'){selectedDomain=id;await navigate('review')}
else if(cmd==='phase-days'){const input=$('#phase-question');if(page==='review'&&input)localStorage.setItem(phaseQuestionKey(),input.value);phaseDays=Number(id)===30?30:7;await draw()}
else if(cmd==='phase-refresh'){await loadPhase(true);await draw()}
else if(cmd==='local-refresh'){await draw()}
else if(cmd==='stage-review'){const question=($('#phase-question')?.value||'').trim(),p=currentPhase()?.period;const range=p?.start&&p?.end?`${p.start} 至 ${p.end}（${p.timezone||'配置时区'}）`:`近 ${phaseDays} 天`;seedChat(`请复盘这段时间：${range}。结合本轮实际阶段资料和「让我伟大」方法，先区分主线、实际行动、本人想法与外部反馈，找出最影响结果的一个卡点，给出下一步与回看条件。没有发布证据时说明未知，不把历史方法算作近期成果。${question?'\n这次我特别想聊：'+question:''}`);persistChatState({useStage:true,stageDays:phaseDays,intent:'phase_review'});const key=chatKey();await navigate('chat');if(page==='chat'&&chatKey()===key)await sendChat()}

else if(cmd==='save-review'||cmd==='save-review-action'||cmd==='save-review-index'){const fields=['main','obstacle','learn','result','next'],values=Object.fromEntries(fields.map(k=>[k,$('#review-'+k).value.trim()]));if(!values.main||!values.result)throw Error('请至少写下当前主线和真实结果；尚未行动也可以如实记录。');const body=[['主线',values.main],['卡点',values.obstacle],['学什么',values.learn],['实际结果',values.result],['下一步',values.next]].map(([h,t])=>'## '+h+'\n'+(t||'暂未记录')).join('\n\n');const n=await api('/api/notes',{title:S.date+' · '+clip(values.main,45),body,kind:'review',goal_id:$('#review-goal').value,index:cmd==='save-review-index',request_id:draftId(body)});localStorage.removeItem('growth-review-draft');await refresh(false);if(cmd==='save-review-action'){recordForm('note:'+n.id);$('#record-title').value=values.next||values.main;if($('#record-mode')&&$('#review-goal')?.value){$('#record-mode').value='action';$('#record-goal').value=$('#review-goal').value;toggleRecordMode()}}else{page='notes';await draw()}toast('复盘已保存。');if(cmd==='save-review-index')watchIndex().catch(e=>toast(e.message))}
else if(cmd==='method'){const m=list(S.methods).find(m=>m.id===id);if(m)open(`<div class="eyebrow">本项目登记的方法 · ${esc(m.id)}</div><h2>${esc(m.title)}</h2><div class="markdown"><ol>${list(m.steps).map(t=>'<li>'+esc(plain(t))+'</li>').join('')}</ol></div><h3>留下什么结果</h3><ul>${list(m.outputs).map(t=>'<li>'+esc(plain(t))+'</li>').join('')}</ul><div class="actions">${list(m.advisor_slugs).map(slug=>btn('阅读 '+esc(advisor(slug)?.title||slug),'advisor:'+slug,'small')).join('')}</div><details><summary>方法来源与说明</summary>${list(m.source_urls).map(u=>'<p>'+link(u,'来源原文')+'</p>').join('')}<p class="subtle">${esc(m.license_basis||'')}</p></details>`,true)}
else if(cmd==='library-domain'){selectedDomain=id;advisorQuery='';advisorCategory='';await draw()}
else if(cmd==='library-all'){selectedDomain='';advisorQuery='';advisorCategory='';await draw()}
else if(cmd==='advisor')await enterAdvisor(id);
else if(cmd==='resume'){const l=S.learning.find(l=>l.id===id);await enterAdvisor(l.advisor,l.file_id)}
else if(cmd==='reader-file'){stashReader();const slug=readerSlug,r=await api('/api/read?id='+encodeURIComponent(id));if(page!=='reading'||readerSlug!==slug)return;reading=r;await renderReader();restoreReadingPosition()}
else if(cmd==='learning-save'){const insight=$('#learning-insight').value;if(id==='reading'&&!$('#learning-position').dataset.changed){const body=$('.reader-main'),p=Math.round(Math.max(0,Math.min(1,(window.scrollY-body.offsetTop)/Math.max(1,body.offsetHeight-innerHeight*.8)))*100);$('#learning-position').value=p;$('#position-value').textContent=p+'%'}if(id==='practiced'&&!insight.trim())throw Error('写下实际运用的结果，再记录为已实践。');await api('/api/learning',{advisor:readerSlug,file_id:reading.id,status:id,insight,goal_id:$('#learning-goal').value,position:id==='read'||id==='practiced'?100:Number($('#learning-position').value)});stashReader();await refresh(false);toast(id==='reading'?'阅读位置和理解已保存，下次可以继续。':id==='read'?'已记录读完；有用的部分，可以继续落成行动。':'实践结果已保存。')}
else if(cmd==='learning-note'){noteSeed={kind:'learning',source:reading.id,title:'关于'+readerInfo.title+'的理解',body:$('#learning-insight').value,goal_id:$('#learning-goal').value};noteForm(noteSeed)}
else if(cmd==='reader-chat'){stashReader();const insight=$('#learning-insight')?.value;seedChat(`刚读了「${reading.title}」${insight?'，我的理解是：\n'+insight:''}\n请结合实际处境，讨论如何运用。`,[{id:reading.id,title:reading.title}]);await navigate('chat')}
else if(cmd==='learning-history'){open('<div class="eyebrow">真实阅读与运用记录</div><h2>我的学习足迹</h2>'+S.learning.map(l=>`<article class="note"><div class="row spread"><h3>${esc(advisor(l.advisor)?.title||l.advisor)}</h3>${tag(statuses[l.status]||l.status)}</div><small>${time(l.updated_at||l.read_at)} · 阅读位置 ${Number(l.position)||0}%</small><p>${esc(l.insight||'还没有写下理解。')}</p>${btn('继续这份原文','resume:'+l.id,'linkbtn')}</article>`).join(''))}
else if(cmd==='read')await showRead(id);
else if(cmd==='read-chat'){addRef(reading);close();if(page!=='chat')await navigate('chat');else updateContext()}
else if(cmd==='select-ref'){const c=contextCandidates.find(r=>r.id===id);if(c)addRef(c);updateContext()}
else if(cmd==='remove-ref'){selectedRefs=selectedRefs.filter(r=>r.id!==id);updateContext()}
else if(cmd==='context-search'){const q=$('#context-query').value.trim();if(!q)throw Error('先输入一个关键词。');const r=await api('/api/search?q='+encodeURIComponent(q));contextCandidates=r.results||[];contextWarnings=contextCandidates.length?[]:['没有匹配这个词，换一个更具体的关键词试试。'];updateContext()}
else if(cmd==='recommend-context'){await requestContext($('#chat-text').value);toast(contextCandidates.length?'相关资料已在右侧列出。你可以回读、移除，再预览发送。':'这次没有找到相关资料，可以换一个词继续查找。')}
else if(cmd==='quote-source'){const q=S.quote;if(!q)return;open(`<div class="eyebrow">每日提醒 · 出处</div><h2>${esc(q.advisor)}</h2>${tag(q.type)}<blockquote>${esc(q.text)}</blockquote><p>${esc(q.original||'原文请查看来源')}</p><p class="subtle">${esc(q.source_locator||'')}</p><p>${link(q.source_url,'查看原始来源')}</p><p class="subtle">行动思考问题由工作台撰写，不是顾问原话。</p>`)}
else if(cmd==='quote-next'){S.quote=await api('/api/quote?offset='+ ++quoteOffset);await draw()}
else if(cmd==='quote-chat'){const q=S.quote;seedChat(`今天的提醒是「${q.text}」，${q.advisor}，${q.type}。来源：${q.source_url}\n请结合我的处境，帮我把这个提醒变成一个适合今天的小行动。`);await navigate('chat')}
else if(cmd==='new-chat'){stashChat();newDraft();await draw();$('#chat-text')?.focus()}
else if(cmd==='session'){sessionId=id;await draw()}
else if(cmd==='preview'){const key=chatKey(),r=await api('/api/chat/preview',chatSnapshot());if(page!=='chat'||chatKey()!==key)return;$('#send-preview').innerHTML=`<div class="context"><div class="eyebrow">本轮发送预览</div><h3>确认这些内容再发送</h3>${councilPreviewHTML(r.advisor_council)}<p class="organize-preview">${r.organize===true?'回复后整理你明确表达的目标与记录；建议保持候选，日期不明确就留空。':'本轮只讨论，不自动整理目标与记录。'}</p><p>你的问题、${Number(r.history_count)||0} 条历史、${list(r.contexts).length} 份额外资料。</p><details open><summary>当前问题</summary><pre>${esc(r.message)}</pre></details><details><summary>携带的历史 · ${r.history_count} 条</summary><pre>${esc(list(r.history).map(h=>h.role+'：'+h.text).join('\n\n'))}</pre></details>${r.contexts.map(c=>`<details><summary>${esc(c.title)} · ${esc(c.kind)}</summary><pre>${esc(c.text)}</pre></details>`).join('')}<div class="actions">${btn('发送当前内容','send-direct','primary')}${btn('返回修改','dismiss-preview','linkbtn')}</div><small>本轮模型：${esc(modelLabel(r.effective_model||r.model||modelCatalog?.default_model))}</small></div>`;const ctx=$('.chat-context');ctx.open=true;$('#send-preview').scrollIntoView({behavior:'smooth',block:'nearest'})}
else if(cmd==='dismiss-preview')invalidatePreview();
else if(cmd==='send')await sendChat(id);
else if(cmd==='send-direct')await sendChat();
else if(cmd==='retry-send')await sendChat(null,true);
else if(cmd==='restore-failed'){const d=currentDraft();const text=[d.text,d.failedText].filter(Boolean).join('\n\n');persistChatState({text,failedText:'',sendError:''});$('#chat-text').value=text;renderChatFailure();updateSendButton();$('#chat-text').focus()}
else if(cmd==='latest-messages'){const box=$('#messages');box.scrollTop=box.scrollHeight;$('#new-replies').hidden=true}
else if(cmd==='restore-legacy'){const text=localStorage.getItem('growth-chat-draft');if(text){seedChat(text,[]);localStorage.setItem('upward-legacy-restored:'+dataScope,'yes');await draw()}}
else if(cmd==='toggle-context'){const ctx=$('.chat-context');ctx.open=!ctx.open}
else if(cmd==='starter'){stashChat();if(currentDraft().text.trim()){seedChat(id);await draw();toast('原草稿已保留，已打开独立讨论。')}else{persistChatState({text:id});$('#chat-text').value=id;updateSendButton()}$('#chat-text').focus()}
else if(cmd==='organize-job'){await api('/api/chat/organize',{id});await refresh(false);await loadMessages();announceChange();toast('已重试整理；请核对下方实际保存结果。')}
else if(cmd==='cancel'){await api('/api/chat/cancel',{id});await loadMessages()}
else if(cmd==='retry'){const j=currentJob()?.id===id?currentJob():S.jobs.find(j=>j.id===id),d=currentDraft();if(!j?.message)throw Error('暂时找不到原问题，请刷新后重试。');persistChatState({text:d.text.includes(j.message)?d.text:[d.text,j.message].filter(Boolean).join('\n\n')});$('#chat-text').value=currentDraft().text;updateSendButton();$('#chat-text').focus();toast('原问题已恢复；核对后可发送。')}
else if(cmd==='save-message'){const m=lastMessages.find(m=>m.id===id);noteSeed={body:m.text,kind:m.reply_context?.intent==='phase_review'?'review':'conversation',source:'codex:'+m.job_id,title:m.reply_context?.intent==='phase_review'?'近'+(m.reply_context.stage_days||7)+'天阶段复盘':'Codex 讨论结论'};noteForm(noteSeed)}
else if(cmd==='record')recordForm(id);
else if(cmd==='save-record'){const common={source_id:recordSource,due:$('#record-due').value};if($('#record-mode').value==='action'){await api('/api/action-from-record',{...common,goal_id:$('#record-goal').value,text:$('#record-title').value,criterion:$('#record-why').value})}else{const did=$('#record-domain').value;await api('/api/goal-from-record',{...common,title:$('#record-title').value,why:$('#record-why').value,domain_id:did,domain:domain(did)?.title||'个人自定',priority:Number($('#record-priority').value),steps:$('#record-steps').value.split('\n').map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}))})}close();page='goals';await refresh();toast('已经加入计划，并保留了这条原始记录。')}
else if(cmd==='search'){knowledgeQuery=$('#knowledge-query').value;const r=await api('/api/search?q='+encodeURIComponent(knowledgeQuery));$('#search-results').innerHTML=`<div class="row spread"><h2>查到 ${r.results.length} 条相关内容</h2><small>关键词：${esc(knowledgeQuery)}</small></div>`+r.results.map(x=>`<article class="search-result"><div class="row spread"><h3>${esc(x.title)}</h3>${tag((x.collection||'资料')+' · '+(x.status||'可回读'))}</div><p>${esc(x.excerpt)}</p>${btn('回读原文 →','read:'+x.id,'linkbtn')}</article>`).join('')+(r.results.length?'':'<div class="empty">没有匹配这个词。可以缩短关键词，或换一个更具体的说法。</div>')}
}
function toggleRecordMode(){const isAction=$('#record-mode').value==='action';$('#record-existing').hidden=!isAction;$('#record-goal-fields').hidden=isAction}
document.addEventListener('click',async e=>{const n=e.target.closest('[data-page],[data-action]');if(!n)return;e.preventDefault();try{n.disabled=true;if(n.dataset.page)await navigate(n.dataset.page);else await action(n.dataset.action)}catch(err){actionError(err.message)}finally{n.disabled=false;if(n.dataset.action==='send-direct')updateSendButton()}});
document.addEventListener('input',e=>{const id=e.target.id;if(e.target.closest('#view')&&!['advisor-search','knowledge-query','context-query'].includes(id))viewHasEdits=true;if(id==='phase-question')localStorage.setItem(phaseQuestionKey(),e.target.value);if(id==='goal-intent')localStorage.setItem('growth-goal-intent',e.target.value);if(id==='capture')localStorage.setItem('growth-draft',e.target.value);if(id==='chat-text'){persistChatState({text:e.target.value});invalidatePreview();updateSendButton()}if(id==='advisor-search'){advisorQuery=e.target.value;$('#advisor-results').innerHTML=advisorTable()}if(id==='learning-insight')stashReader();if(id==='learning-position'){stashReader();$('#position-value').textContent=e.target.value+'%';e.target.dataset.changed='true'}if(e.target.dataset.review){const d=reviewDraft();d[e.target.dataset.review]=e.target.value;d.goal_id=$('#review-goal').value;localStorage.setItem('growth-review-draft',JSON.stringify(d))}});
document.addEventListener('change',async e=>{try{const id=e.target.id;if(id==='chat-model'){persistChatState({model:e.target.value||null});invalidatePreview()}if(id==='learning-goal')stashReader();if(id==='category'){advisorCategory=e.target.value;$('#advisor-results').innerHTML=advisorTable()}if(id==='include-goals'||id==='include-stage'){stashChat();invalidatePreview()}if(id==='organize-reply'){organizeDraft=e.target.checked;stashChat();invalidatePreview()}if(id==='session-select'){stashChat();if(e.target.value.startsWith('draft:')){draftKey=e.target.value;sessionId=''}else sessionId=e.target.value;restoreChatState();saveDraftStore();await draw()}if(id==='record-mode')toggleRecordMode();if(id==='review-goal'){const d=reviewDraft();d.goal_id=e.target.value;localStorage.setItem('growth-review-draft',JSON.stringify(d))}if(e.target.dataset.step){const [gid,sid]=e.target.dataset.step.split(':'),g=structuredClone(S.goals.find(g=>g.id===gid));g.steps.find(s=>s.id===sid).done=e.target.checked;await api('/api/goals',g);await refresh();toast('行动状态已保存；可以在「安排与结果」补充证据。')}}catch(err){actionError(err.message);if(e.target.dataset.step)e.target.checked=!e.target.checked}});
document.addEventListener('compositionstart',()=>{composing=true});document.addEventListener('compositionend',()=>{composing=false;compositionEnded=Date.now()});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-text'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!composing&&e.keyCode!==229&&Date.now()-compositionEnded>100){e.preventDefault();sendChat().catch(err=>actionError(err.message));return}if(e.key==='Enter'&&['knowledge-query','context-query'].includes(e.target.id)){e.preventDefault();action(e.target.id==='knowledge-query'?'search':'context-search').catch(err=>toast(err.message))}});
let wasNarrow=window.innerWidth<=760;window.addEventListener('resize',()=>{const narrow=window.innerWidth<=760;if(narrow&&!wasNarrow&&$('.chat-context'))$('.chat-context').open=false;wasNarrow=narrow});
window.addEventListener('beforeunload',()=>{stashChat();stashReader()});window.addEventListener('focus',()=>syncBackground());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncBackground()});window.addEventListener('storage',e=>{if(e.key==='growth-state-change')syncBackground()});
$('#close-modal').onclick=close;
refresh().catch(e=>{$('#view').innerHTML='<section class="panel"><h1>暂时没能读到工作台。</h1><p>请确认本地服务已启动，再刷新页面。浏览器中保存的输入草稿仍然保留。</p></section>';toast(e.message)});
